(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c51"]=[{"id":"00007884","register_sub_id":"101","register_pk":"108864","name":"小泉家住宅主屋","kana":"こいずみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県越前市二階堂町11字下稲荷8","lat":35.88793132,"lng":136.04545881,"geo_status":"db","era":"江戸後期／平成20改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋一部二階建、茅葺一部瓦葺、建築面積324㎡","structure_material":"木造平屋一部二階建","registered":"2009.11.02(平成21.11.02)","register_no":"18-0081","desc":"敷地の中央に南面して建つ。南北棟の入母屋造妻入茅葺の上屋に、両側面後寄りと背面に切妻造桟瓦葺屋根を付け、周囲に深い桟瓦葺の下屋をまわし、複雑な外観をつくる。内部は広間を中心に南に土間、西に座敷、北に仏間などを配する特殊な平面になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007884"},{"id":"00007352","register_sub_id":"101","register_pk":"108334","name":"幸道家住宅主屋","kana":"こうどうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県鯖江市田所町9字北川瀬山11","lat":35.974197,"lng":136.180984,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積185㎡","structure_material":"木造2階一部平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"18 － 0069","desc":"北東の角地に敷地を占める。南側通り沿いに、切妻造桟瓦葺の木造２階建を設け、西面に入母屋造桟瓦葺の座敷棟を張り出し、さらに北側の低い位置に小さな入母屋破風を付ける。黒漆喰仕上げの外壁や、起り屋根の複雑な構成により重厚な外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007352"},{"id":"00007353","register_sub_id":"101","register_pk":"108335","name":"幸道家住宅離れ","kana":"こうどうけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県鯖江市田所町9字北川瀬山11","lat":35.97427,"lng":136.181076,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積43㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"18 － 0070","desc":"主屋の北面東寄りに隣接する。棟の高い木造平屋建。南北棟の起りのある入母屋造で、北と西面に下屋庇を付ける。東・北面の外壁は黒漆喰仕上げ腰竪板張で閉鎖的とし、庭園側の西面は土庇を付け開放的に扱う。内部はトコと棚をもつ八畳と六畳の続き座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007353"},{"id":"00011293","register_sub_id":"101","register_pk":"209129","name":"齋藤家住宅米蔵","kana":"さいとうけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県鯖江市舟津町四丁目1421","lat":35.932675,"lng":136.180855,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積71㎡","structure_material":"土蔵造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"18－0160","desc":"敷地東に、旧北陸道に接して建てられる。南北棟で、西側には下屋を架けて、広い蔵前を構える。建ちの高い平屋建土蔵で、東面に高窓を二所開く。外壁は上部を白漆喰塗とし、下部は簓子下見板張とする。街道沿いに旧家の格式を示し、屋敷地の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011293"},{"id":"00011296","register_sub_id":"101","register_pk":"209132","name":"齋藤家住宅小屋","kana":"さいとうけじゅうたくこや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県鯖江市舟津町四丁目1421","lat":35.932771,"lng":136.180829,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"18－0163","desc":"主屋の東側、米蔵の北側に表門からの動線に沿って東西棟で建つ。桁行一三メートル、梁間二・〇メートルの細長い建物で、内部は大きく三室に区切る。かつては厠や物置として用いられた。主屋玄関前と庭との間を区切る役割を持ち、敷地内景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011296"},{"id":"00011291","register_sub_id":"101","register_pk":"209127","name":"齋藤家住宅主屋","kana":"さいとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県鯖江市舟津町四丁目1421","lat":35.9329,"lng":136.180641,"geo_status":"db","era":"江戸後期／江戸末期・明治10増築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋一部2階建、瓦葺、建築面積368㎡","structure_material":"木造平屋一部2階建","registered":"2016.11.29(平成28.11.29)","register_no":"18－0158","desc":"鯖江市の南端、旧北陸道が日野川の渡しに向けて矩折れになる角地に面して敷地を構える。主屋は敷地中央に建ち、東西棟の主棟と、藩主招請に合せて建てたという南北棟で北方に突き出した座敷棟からなる。正面の屋根妻部を塗込めており、当地の特色を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011291"},{"id":"00011295","register_sub_id":"101","register_pk":"209131","name":"齋藤家住宅新蔵","kana":"さいとうけじゅうたくしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県鯖江市舟津町四丁目1421","lat":35.93304,"lng":136.180375,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積84㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"18－0162","desc":"中蔵の北側に接して建つ。南北棟で、中蔵の蔵前に向けて南辺東端間に出入口を設ける。土蔵造二階建で、腰部を高く下見板張とする西面以外は、腰部を石張風、その上を高く石積風に見せ、さらに上部は軒まで漆喰塗込とする。外観意匠に意を凝らした土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011295"},{"id":"00011294","register_sub_id":"101","register_pk":"209130","name":"齋藤家住宅中蔵","kana":"さいとうけじゅうたくなかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県鯖江市舟津町四丁目1421","lat":35.93294,"lng":136.180363,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積89㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"18－0161","desc":"敷地西側に、主屋から庭を挟んで建つ。南北棟で、東側には下屋を架けて、蔵前とする。土蔵造二階建で、西面は上部白漆喰塗、腰部を高く簓子下見板張とする伝統的な外観を見せる一方、東面はモルタル洗出仕上げとする石張風の外観を見せ、対比的な意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011294"},{"id":"00011292","register_sub_id":"101","register_pk":"209128","name":"齋藤家住宅離れ","kana":"さいとうけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県鯖江市舟津町四丁目1421","lat":35.932839,"lng":136.180496,"geo_status":"db","era":"昭和3","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"木造2階建、瓦葺、建築面積114㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"18－0159","desc":"主屋の西に接続して建つ。各階とも北側に廊下を通して、南に居室を並べた二階建である。接客を重視した主屋に対し、より日常生活を意図した近代和風建築となる。一階居間の扇面透欄間や、洗面所の円窓など、数寄屋風の瀟洒な意匠も随所に取り入れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011292"},{"id":"00011298","register_sub_id":"101","register_pk":"209135","name":"齋藤家住宅東門","kana":"さいとうけじゅうたくひがしもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県鯖江市舟津町四丁目1421","lat":35.932898,"lng":136.18086,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.2m","structure_material":"木造","registered":"2016.11.29(平成28.11.29)","register_no":"18－0165","desc":"敷地の東寄り、主屋玄関前と、主屋東庭とを隔てる門。小屋と向かい合って建つ。主屋座敷棟に賓客を迎えるために設けられた間口二・二メートルの門で、控柱を持つ腕木門の形式になる。主要材にケヤキを用い、扉には八双金物などの飾金物を多用して瀟洒に飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011298"},{"id":"00011297","register_sub_id":"101","register_pk":"209133","name":"齋藤家住宅門柱","kana":"さいとうけじゅうたくもんちゅう","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県鯖江市舟津町四丁目1421","lat":35.932839,"lng":136.180917,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、間口2.8m","structure_material":"石造","registered":"2016.11.29(平成28.11.29)","register_no":"18－0164","desc":"敷地の東側、旧北陸道に面して開く表門にあたる。間口二・八メートルで、笏谷石製の主柱と控柱を立てる。主柱は高さ三・一メートルと大型で、上部には段を作り出して装飾とする。県内に散見される笏谷石製門柱の中でもとりわけ大型で、旧家の格式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011297"},{"id":"00015437","register_sub_id":"101","register_pk":"533452","name":"酒井家住宅主屋","kana":"さかいけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県坂井市丸岡町楽間12字楽金3他","lat":36.10932778,"lng":136.30647222,"geo_status":"db","era":"明治後期／大正12年移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積297㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"18 - 0262","desc":"九頭竜川右岸に位置する実業家の主屋。敷地中央に西面して建つ二階建入母屋造妻入桟瓦葺で正面に入母屋造玄関を付す。一階は広間の東に２列六室を並べ、北に台所を延ばす。二階は一六畳半座敷で格天井を腰折状に張るなど特徴的。大規模で上質な近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015437"},{"id":"00015440","register_sub_id":"101","register_pk":"533455","name":"酒井家住宅家財蔵","kana":"さかいけじゅうたくかざいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県坂井市丸岡町楽間12字楽金3他","lat":36.10948889,"lng":136.30651944,"geo_status":"db","era":"昭和5年頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積61㎡","structure_material":"土蔵造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"18 - 0265","desc":"主屋の北に位置し、家財など収納する土蔵。二階建切妻造桟瓦葺で南面に戸口を設け、下屋を付して蔵前とする。外壁は漆喰塗仕上で押縁下見板を高く張る。各階１室の板敷で二階中央に独立柱を立て、小屋は垂木構造。戸口や窓に鉄扉を吊るなど厳重な構えの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015440"},{"id":"00015441","register_sub_id":"101","register_pk":"533456","name":"酒井家住宅北土蔵","kana":"さかいけじゅうたくきたどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県坂井市丸岡町楽間12字楽金3他","lat":36.10953611,"lng":136.30638611,"geo_status":"db","era":"昭和5年頃／令和5年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積79㎡","structure_material":"土蔵造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"18 - 0266","desc":"家財蔵の西に位置し、かつて家財などを収納した土蔵。二階建切妻造桟瓦葺で南面に戸口を設け、下屋を付して蔵前とする。外壁漆喰塗仕上、簓子下見板を高く張り、西妻に家紋を掲げる。小屋組は登梁形式。家財蔵と並び建ち、敷地北西の屋敷構えをつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015441"},{"id":"00004747","register_sub_id":"101","register_pk":"105737","name":"坂井家住宅主屋","kana":"さかいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県坂井市三国町北本町3-9-32","lat":36.21422131,"lng":136.14694128,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積75㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"18 － 0041","desc":"切妻造妻入の主体部の前方に平入の表屋を付けた「かぐら建て」の町家。間口３間半，奥行６間半，桟瓦葺で，１階通り土間，２階廊下に沿って座敷を一列に並べる。繊細な出格子を付け，２階両端に袖壁を備える整った外観は，歴史的な町並みの中でも一際目立つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004747"},{"id":"00015439","register_sub_id":"101","register_pk":"533454","name":"酒井家住宅新座敷","kana":"さかいけじゅうたくしんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福井県","address":"福井県坂井市丸岡町楽間12字楽金4他","lat":36.10911389,"lng":136.30645,"geo_status":"db","era":"昭和26年頃","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積116㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"18 - 0264","desc":"洋館の南に渡廊下で接続する賓客用の離れ座敷。平屋建入母屋造桟瓦葺の東西棟で、内部は東に続き間座敷、北西に茶室、南西に水廻りを配す。座敷は床、琵琶床、棚、付書院を備え、天井は折上小組格天井。北と東に縁を廻らし庭を望む、端正で華やかな座敷棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015439"},{"id":"00015443","register_sub_id":"101","register_pk":"533458","name":"酒井家住宅正門及び西塀","kana":"さかいけじゅうたくせいもんおよびにしべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県坂井市丸岡町楽間12字楽金","lat":36.10945278,"lng":136.306275,"geo_status":"db","era":"昭和5年頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"正門 木造、瓦葺、間口2.8m 西塀 木造、瓦葺、総延長29m","structure_material":"正門 木造","registered":"2025.08.06(令和7.08.06)","register_no":"18 - 0268","desc":"敷地西面中央に開く薬医門と両脇に続く板塀。正門は基壇上に建つ切妻造本瓦葺で、両脇に潜戸を付す。天井は吹寄の折上格天井とし、妻飾・欄間・冠木上などに精緻な彫刻を飾る。欄間を唐草の透彫とした西塀と一体となって、華やかで風格ある屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015443"},{"id":"00015445","register_sub_id":"101","register_pk":"533460","name":"酒井家住宅通用門及び南西塀","kana":"さかいけじゅうたくつうようもんおよびなんせいべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"福井県","address":"福井県坂井市丸岡町楽間12字楽金","lat":36.10916389,"lng":136.30635556,"geo_status":"db","era":"昭和26年頃","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"通用門 鉄筋コンクリート造、間口1.5m 南西塀 鉄筋コンクリート造、総延長27m","structure_material":"通用門 鉄筋コンクリート造","registered":"2025.08.06(令和7.08.06)","register_no":"18 - 0270","desc":"敷地南西面に開く鉄筋コンクリート造の門と塀。通用門は外壁モルタル洗出仕上で門柱上部をアーチ形の鉄棒で繋ぎ門口に鉄扉を開く。南西に続く塀はモルタル吹付仕上とし、土台形、柱形、笠木形をモルタル洗出仕上。通用門と一体で通りに歴史的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015445"},{"id":"00004748","register_sub_id":"101","register_pk":"105738","name":"坂井家住宅土蔵","kana":"さかいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県坂井市三国町北本町3-9-32","lat":36.21408017,"lng":136.14686052,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋一部2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造平屋一部2階建","registered":"2005.07.12(平成17.07.12)","register_no":"18 － 0042","desc":"主屋の裏，中庭を介して建つ。桁行３間，梁間２間半，土蔵造，切妻造，桟瓦葺で，東面に下屋を葺き降ろし主屋通り土間から続く通路とし，ここに戸口を開く。たちが高く北面に小窓を開く以外は塗り込めとした堅牢な造りで，屋敷構えに欠くことのできない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004748"},{"id":"00004749","register_sub_id":"101","register_pk":"105739","name":"坂井家住宅荷蔵","kana":"さかいけじゅうたくにぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県坂井市三国町北本町3-9-32","lat":36.21401052,"lng":136.14683262,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積58㎡","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"18 － 0043","desc":"土蔵の南に接続する。桁行５間，梁間３間半，土蔵造，２階建，切妻造，桟瓦葺で，西１間は土蔵から続く通路とし，南面に背戸を開く。入念な造りになる蔵で，九頭竜川に面して下見板張りの南妻を見せて建つ姿は，舟運の盛んだった頃の三国の様子を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004749"},{"id":"00015442","register_sub_id":"101","register_pk":"533457","name":"酒井家住宅西土蔵","kana":"さかいけじゅうたくにしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県坂井市丸岡町楽間12字楽金3他","lat":36.10934444,"lng":136.30623889,"geo_status":"db","era":"昭和5年頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"18 - 0267","desc":"主屋の南西に位置し、米や農具などの収納蔵。二階建切妻造桟瓦葺で、東に戸口を設けて庇を付す。外壁は漆喰塗仕上で軒に鉢巻を廻らし、簓子下見板を高く張る。内部は各階一室で、小屋組は登梁形式とする。西妻に家紋を掲げ、屋敷南西角の景観をつくる西土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015442"},{"id":"00015444","register_sub_id":"101","register_pk":"533459","name":"酒井家住宅南門及び南塀","kana":"さかいけじゅうたくみなみもんおよびみなみべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県坂井市丸岡町楽間12字楽金","lat":36.10928333,"lng":136.30628333,"geo_status":"db","era":"昭和5年頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"南門 木造、瓦葺、間口1.9m 南塀 木造、瓦葺、総延長12m","structure_material":"南門 木造","registered":"2025.08.06(令和7.08.06)","register_no":"18 - 0269","desc":"敷地南辺に開く腕木門と西へ続く板塀。基壇上に建つ南門は切妻造桟瓦葺で、軒は一軒疎垂木。内部は格天井を張り、門口にケヤキの一枚板を両開に吊り、欄間は襷桟とする。南塀は漆喰塗壁で腰は竪板張とする。西土蔵に連なり、敷地南辺の歴史的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015444"},{"id":"00015438","register_sub_id":"101","register_pk":"533453","name":"酒井家住宅洋館","kana":"さかいけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県坂井市丸岡町楽間12字楽金3他","lat":36.10928333,"lng":136.30636667,"geo_status":"db","era":"昭和5年頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積34㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"18 - 0263","desc":"主屋に接続する洋館。鉄筋コンクリート造2階建で外壁モルタル塗に目地を切り石造風。軒中央に唐破風形ペディメントを立上げ家紋を付し、二階は尖頭と半円アーチ窓を交互に開け、西面にバルコニーを付す。屋上から福井市内を望んだと伝わる凝った意匠の洋館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015438"},{"id":"00016502","register_sub_id":"101","register_pk":"574864","name":"清水家住宅主屋","kana":"しみずけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県鯖江市水落町二丁目1128他","lat":35.95804583,"lng":136.18627889,"geo_status":"db","era":"慶応元年（1865）／昭和53年改修","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造平屋建、銅板葺一部瓦葺、建築面積164㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"18 - 0273","desc":"市街地の北部、旧北陸道に面する旧家の主屋。敷地中央に東面して建つ入母屋造妻入で、周囲に下屋を廻らす。東半は踏込土間と囲炉裏のあるイタノマで、上部に梁組を現し、西半は四室を並べ、北西室は床構え付き座敷とする。当地の伝統的な間取をよく残す民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016502"},{"id":"00016503","register_sub_id":"101","register_pk":"574865","name":"清水家住宅東門","kana":"しみずけじゅうたくひがしもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県鯖江市水落町二丁目1127他","lat":35.95804583,"lng":136.18627889,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口3.7m、左右袖壁付","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"18 - 0274","desc":"主屋の正面、通りより引込み建つ腕木門。切妻造平入桟瓦葺で左右前方に桟瓦葺袖塀を延ばす。主柱はクリ材で腕木と控柱で軒桁を支持し、門口に引分の板戸を建てる。門の脇間や塀は漆喰壁で腰は簓子下見板張。笏谷石の棟石を据え、旧家の正面構えを整える東門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016503"},{"id":"00014480","register_sub_id":"101","register_pk":"513894","name":"杉原商店表門","kana":"すぎはらしょうてんおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県越前市不老町17字東町2-3","lat":35.90714167,"lng":136.24436111,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造、瓦葺、間口2.3m、袖塀付","structure_material":"木造","registered":"2023.02.27(令和5.02.27)","register_no":"18 - 0239","desc":"主屋の北に北面する和紙問屋の表門。切妻造桟瓦葺の薬医門で両脇に板塀を付し、西に潜戸を開ける。親柱間に冠木を渡し、肘木で受けた梁に束を立て棟木を受ける。軒は一軒繁垂木。戸口には両開の板戸を吊る。丁寧な造りで通りに面して和紙問屋の表構えを形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014480"},{"id":"00014476","register_sub_id":"101","register_pk":"513890","name":"杉原商店主屋","kana":"すぎはらしょうてんおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県越前市不老町17字東町2-1他","lat":35.90692222,"lng":136.244425,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積307㎡","structure_material":"木造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"18 - 0235","desc":"越前市東部の不老町に位置する和紙問屋の主屋。二階建切妻造妻入桟瓦葺で北に吹放ちの下屋を付し、北東に台所・風呂棟を付属する。一階は二列八室として東西に縁を付し、南西を坊主の間とする。柱や天井などに良材を用いて漆塗で仕上げた上質な近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014476"},{"id":"00014477","register_sub_id":"101","register_pk":"513891","name":"杉原商店西土蔵","kana":"すぎはらしょうてんにしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県越前市不老町17字東町2-1他","lat":35.90701111,"lng":136.24421944,"geo_status":"db","era":"大正6年／平成30年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積145㎡","structure_material":"土蔵造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"18 - 0236","desc":"主屋の西に東面し、和紙製品や道具を収納する土蔵。2階建切妻造平入桟瓦葺で、東に2箇所の戸口を開けて下屋を付す。外壁は漆喰塗仕上で腰壁は簓子下見板張。一階は土間一室で中央に独立柱を立て、二階は板敷一室とする。和紙問屋の繁栄を示す上質な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014477"},{"id":"00014481","register_sub_id":"101","register_pk":"513895","name":"杉原商店納骨堂","kana":"すぎはらしょうてんのうこつどう","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県越前市不老町23字堂谷29-1","lat":35.90705278,"lng":136.24489167,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、銅板葺、面積2.3㎡","structure_material":"鉄筋コンクリート造","registered":"2023.02.27(令和5.02.27)","register_no":"18 - 0240","desc":"敷地南東の高台に位置する和紙問屋の納骨堂。施工は三代師田庄左衛門。基壇上に建つ鉄筋コンクリート造平屋建宝形造銅板葺で、軒は一軒繁垂木とする。外壁に柱、長押を造出し、モルタル塗で仕上げる。小規模ながら貴重な昭和初期の鉄筋コンクリート造納骨堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014481"},{"id":"00014478","register_sub_id":"101","register_pk":"513892","name":"杉原商店東土蔵","kana":"すぎはらしょうてんひがしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県越前市不老町17字東町2-1他","lat":35.90723611,"lng":136.24465278,"geo_status":"db","era":"大正10年／昭和50年頃改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積112㎡","structure_material":"土蔵造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"18 - 0237","desc":"主屋の東に西面し、和紙製品を収納する土蔵。2階建切妻造平入桟瓦葺で西に1箇所の戸口を開けて下屋を付す。外壁は漆喰塗仕上で二階腰まで簓子下見板を高く張る。各階板敷の１室で中央に独立柱を立て、北西に階段を設ける。敷地北東の景観をつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014478"},{"id":"00006454","register_sub_id":"101","register_pk":"107437","name":"高鳥家住宅土蔵","kana":"たかとりけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県小浜市小浜鹿島19","lat":35.49342397,"lng":135.738907,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"18 － 0052","desc":"敷地の北西隅、離れの西方に南北棟で建つ。桁行２間半、梁間２間、切妻造、桟瓦葺の２階建土蔵で、南面に離れの屋根と一連の庇を付けて蔵前とし、戸口を開ける。小屋は梁に束を立て棟を受ける。外部は漆喰塗で、窓庇の持送りや掛子塗の窓扉など造作も丁寧。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006454"},{"id":"00006453","register_sub_id":"101","register_pk":"107436","name":"高鳥家住宅離れ","kana":"たかとりけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県小浜市小浜鹿島19","lat":35.49338196,"lng":135.73894579,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"18 － 0051","desc":"診療所兼住宅の西方に東西棟で建つ。桁行３間半、梁間３間、入母屋造、桟瓦葺の木造平屋建で、診療所兼住宅との間を台所とする。トコと棚、付書院を備えた８畳間と３畳間の２室からなり、東面から南面にかけて縁を廻す。建具を含め繊細なつくりの数寄屋風離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006453"},{"id":"00009453","register_sub_id":"101","register_pk":"194246","name":"瀧波家住宅大蔵","kana":"たきなみけじゅうたくおおぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県鯖江市本町3-232他","lat":35.94775258,"lng":136.18524709,"geo_status":"db","era":"明治20年頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積80㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"18 － 0115","desc":"主屋の北側に東西棟で建つ。土蔵造二階建、桁行一五・二メートル梁間四・八メートル、切妻造桟瓦葺で、東妻面と、南面の出入口二箇所に下屋を設ける。外壁は漆喰塗で腰を石張及び簓子下見板張とし、上階の窓には掛子塗の土戸を吊る。重厚な構えの大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009453"},{"id":"00009451","register_sub_id":"101","register_pk":"194244","name":"瀧波家住宅主屋","kana":"たきなみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県鯖江市本町3-232他","lat":35.9475627,"lng":136.18527802,"geo_status":"db","era":"明治20年頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積172㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"18 － 0113","desc":"旧北陸街道に東面し、木造二階建、切妻造桟瓦葺である。正面は上下階とも出桁造で出格子を構え、両端に袖うだつを設けるなど、当地方の伝統的な町家形式を伝える。一方で後方の張出し部では、下階を石造風にモルタル洗出しで仕上げるなど洋風意匠を加味する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009451"},{"id":"00009454","register_sub_id":"101","register_pk":"194247","name":"瀧波家住宅道具蔵","kana":"たきなみけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県鯖江市本町3-232他","lat":35.94771499,"lng":136.18517047,"geo_status":"db","era":"明治20年頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"18 － 0116","desc":"離れ座敷と大蔵の間に南北棟で建つ。土蔵造二階建、桁行六・五メートル梁間三・八メートル、切妻造桟瓦葺で、南妻面を戸口として下屋を設ける。外壁は漆喰塗で腰を石張とし、軒蛇腹などを黒漆喰仕上げとするほか、戸口の土戸に大振りの分銅模様を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009454"},{"id":"00009452","register_sub_id":"101","register_pk":"194245","name":"瀧波家住宅離れ座敷","kana":"たきなみけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県鯖江市本町3-232他","lat":35.94766787,"lng":136.18514286,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、銅板葺、建築面積51㎡、渡廊下付","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"18 － 0114","desc":"主屋後方に中庭を挟んで建ち、木造平屋建、切妻造銅板葺である。和室二室を南北に並べ、周囲に下屋の縁を廻らす。八畳の主室にトコと床脇を備え、縁の軒廻りには丸太材を使用して数寄屋風の取入れる。商家の屋敷構えを構成する開放的なつくりの離れである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009452"},{"id":"00007485","register_sub_id":"101","register_pk":"108467","name":"竹内家住宅主屋","kana":"たけうちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県鯖江市杉本町1字清水添38-1他","lat":35.98477921,"lng":136.16905589,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積191㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"18 － 0077","desc":"七曲りの西に占める敷地の中央に南北棟で建つ。桁行１５ｍ梁間７．６ｍ規模の木造２階建。切妻造妻入桟瓦葺で、周囲に下屋をまわし、大棟南寄りに大きな越屋根を付ける。妻面など上部壁は束と貫を格子状に組み、その間を漆喰仕上げとする特徴的な意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007485"},{"id":"00015302","register_sub_id":"101","register_pk":"532426","name":"舘家住宅内蔵","kana":"たちけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県鯖江市和田町17字二ノ和田10-1他","lat":35.951275,"lng":136.14073056,"geo_status":"db","era":"明治前期／昭和40年代改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積36㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"18 - 0254","desc":"主屋の東に位置する家財蔵。切石積基礎に建つ、二階建切妻造平入桟瓦葺で外壁漆喰塗仕上、腰は南・東面は簓子下見板張、北・西面はモルタル塗仕上とする。各階一室の板敷で、二階上部は束立の和小屋を現す。敷地の一角を占め、旧家の屋敷構えを形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015302"},{"id":"00015301","register_sub_id":"101","register_pk":"532425","name":"舘家住宅主屋","kana":"たちけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県鯖江市和田町17字二ノ和田10-1他","lat":35.95134167,"lng":136.14059444,"geo_status":"db","era":"江戸末期／昭和10年・平成21年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積256㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"18 - 0253","desc":"鯖江市西方の集落の高台に位置する旧家の主屋。二階建入母屋造妻入桟瓦葺で、南を土間と板間、北に二列六室を並べ、北東に離れを突出する。西列中央の座敷は床、違棚、天袋を備えた端正なつくり。軸部に太いケヤキを用い、越前の伝統的な平面を踏襲した民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015301"},{"id":"00015303","register_sub_id":"101","register_pk":"532427","name":"舘家住宅外蔵","kana":"たちけじゅうたくそとぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県鯖江市和田町17字二ノ和田10-1他","lat":35.95126667,"lng":136.14042778,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積39㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"18 - 0255","desc":"主屋の南西に建つ道具蔵。二階建切妻造平入桟瓦葺で、南面東寄と西面南寄に戸口を開け、下屋を付す。外壁は漆喰塗仕上とし腰は簓子下見板を高く張る。各階一室の板敷で、北東に階段を設け、二階上部は束立の和小屋を現す。小規模ながら屋敷景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015303"},{"id":"00015304","register_sub_id":"101","register_pk":"532428","name":"舘家住宅長屋門","kana":"たちけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県鯖江市和田町17字二ノ和田10-1他","lat":35.95118056,"lng":136.14054444,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"18 - 0256","desc":"通りに南面する長屋門。切石積基礎に建つ、入母屋造桟瓦葺で軒は出桁造。外壁漆喰塗仕上で腰簓子下見板張。正面中央に石段を設けて、潜戸付の門口を構え、東に漬物小屋、西に物置を配す。各室土間で小屋組を現す。間口の大きな門構えが旧家の風格を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015304"},{"id":"00011125","register_sub_id":"101","register_pk":"205232","name":"丹巌洞草庵","kana":"たんがんどうそうあん","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"江戸","pref":"福井県","address":"福井県福井市加茂河原1-555他","lat":36.059743,"lng":136.196187,"geo_status":"db","era":"弘化3頃","year":1846,"year_source":"db","year_min":1846,"year_max":1846,"year_label":null,"structure":"土蔵造2階一部木造平屋建、瓦葺、建築面積69㎡","structure_material":"土蔵造2階一部木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"18 - 0156","desc":"福井藩医、山本瑞庵の別荘として建てられたと伝わる。二階建の土蔵に、木造平屋建の六畳茶室等を併設した複雑な平面を呈す。二階には船底状に天井を張り、壁、天井とも襖紙を貼り付けて塗込めたように見せる。土蔵の概念に捉われず数寄屋風の内装でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011125"},{"id":"00002539","register_sub_id":"101","register_pk":"103529","name":"南部酒造場西蔵","kana":"なんぶしゅぞうじょうにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県大野市元町6-9～10","lat":35.984741,"lng":136.48957444,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積53㎡","structure_material":"土蔵造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"18 － 0020","desc":"大蔵の西北方に建つ。桁行５間，梁間３間規模，南北棟，切妻造，鉄板葺，平入の２階建土蔵で，東面に入口を設ける。南部家の家財蔵で，外観は軒下に方杖をつけ，内部では登り梁に後補とみられるアングル材を添わせる特異な小屋組が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002539"},{"id":"00011688","register_sub_id":"101","register_pk":"210704","name":"西野家住宅蚊帳蔵・味噌蔵・紙蔵","kana":"にしのけじゅうたくかやぐら・みそぐら・かみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県越前市定友町4字福岡8-1","lat":35.913718,"lng":136.246089,"geo_status":"db","era":"江戸末期／大正14年頃増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積218㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"18-0179","desc":"敷地南東で主屋に面して建つ。梁間四間で、桁行東三間の蚊帳蔵と中央二間の味噌蔵は一連の切妻屋根で、西六間の紙蔵は増築で棟を一段高くする。北面全面に下屋を付け、扉枠に家紋や社標を飾る。内部は真壁で、小屋は登梁とする。屋敷の拡充過程を示す大型の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011688"},{"id":"00011686","register_sub_id":"101","register_pk":"210702","name":"西野家住宅主屋","kana":"にしのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県越前市定友町4字福岡8-1","lat":35.913922,"lng":136.246079,"geo_status":"db","era":"江戸末期／大正前期移築、平成2年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、鋼板葺、建築面積221㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"18-0177","desc":"池田町の農家を移築し、大正期に背面へ増築したもの。移築部は梁間四間、桁行六間で、東妻面に卯建を立ち上げ当地方特有の外観を見せる。内部は六間取で、面皮材を用いた床構えなどを残す。増築部はガラス戸を多用し開放的な外観。それぞれ時代の特徴を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011686"},{"id":"00011689","register_sub_id":"101","register_pk":"210705","name":"西野家住宅新蔵・中蔵・大蔵","kana":"にしのけじゅうたくしんぐら・なかぐら・おおぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市定友町4字福岡8-1","lat":35.913903,"lng":136.245725,"geo_status":"db","era":"明治22年頃／昭和前期増築、平成5年改修","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"土蔵造2階建、鋼板葺、建築面積154㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"18-0180","desc":"敷地北西で東面する。梁間三間で、北四間の大蔵と、南五間の新蔵を一間半の中蔵で繋ぐ。東面全面に下屋を付ける。大蔵の扉口は、土戸・板戸・格子戸を吊る重厚な造りで、新蔵、中蔵ともに黒漆喰を用いて正面を飾り、敷地景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011689"},{"id":"00011690","register_sub_id":"101","register_pk":"210706","name":"西野家住宅茶室","kana":"にしのけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市定友町4字福岡8-1","lat":35.913732,"lng":136.245868,"geo_status":"db","era":"明治42年頃","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"18-0181","desc":"敷地南西に建つ。切妻造、桟瓦葺で、東面に玄関を開く。六畳と四畳半を南北に並べ、南西に矩折れに廊下を廻らす。外壁は漆喰塗で腰板壁とし、内部は軸部に透漆、天井廻縁や棹縁に黒漆を施すが、床柱と落掛は素木のままとする。和紙生産の繁栄を今に伝える茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011690"},{"id":"00011687","register_sub_id":"101","register_pk":"210703","name":"西野家住宅離れ","kana":"にしのけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市定友町4字福岡8-1","lat":35.913965,"lng":136.245901,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積87㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"18-0178","desc":"主屋の背後に接続する。座敷二室を並べ、庭に面する南側は板縁と土間を設け、ガラス戸を建て込み開放的に構える。床構えは銘木を用い、彫刻欄間に優れた技術を施しており見応えがある。東側の便所も手の込んだ造作で、竹や梅をモチーフとした装飾で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011687"},{"id":"00011691","register_sub_id":"101","register_pk":"210707","name":"西野家住宅塀","kana":"にしのけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市定友町4字福岡8-1","lat":35.914001,"lng":136.245983,"geo_status":"db","era":"昭和12年／昭和前期増築","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、瓦葺、延長33m","structure_material":"木造","registered":"2017.06.28(平成29.06.28)","register_no":"18-0182","desc":"敷地北面を画す。東半は笏谷石の切石積、西半は亀甲積と異なる石垣上に建ち、柱上は肘木状の腕木で出桁を受け、桟瓦葺の屋根を架ける。外壁は真壁で、庭園部では松皮菱の開口を設ける。外側は簓子下見張で上部は色土壁とし、街路景観を形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011691"},{"id":"00015173","register_sub_id":"101","register_pk":"530597","name":"西野百助家住宅主屋","kana":"にしのひゃくすけけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市定友町9字辻堂2他","lat":35.914175,"lng":136.24619444,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積305㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"18 - 0243","desc":"越前和紙産地の旧今立町に位置する製紙業者の主屋。通りから引込み東面して建つ大規模な2階建入母屋造妻入桟瓦葺。東に玄関、西に仏間と座敷を配し、北東に台所棟を付す。軸部はスギの良材を用いて透漆塗とし、材料から仕上まで吟味した良質な近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015173"},{"id":"00015174","register_sub_id":"101","register_pk":"530598","name":"西野百助家住宅北土蔵","kana":"にしのひゃくすけけじゅうたくきたどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市定友町9字辻堂2他","lat":35.91436111,"lng":136.24595833,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"土蔵造2階建一部木造平屋建、瓦葺、建築面積95㎡","structure_material":"土蔵造2階建一部木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"18 - 0244","desc":"敷地北西隅に位置し、亀甲積石垣上に建つ家財蔵。２階建切妻造の南北棟の南に平屋建切妻造の８畳を接続し、東面に一連で下屋を付す。外壁は漆喰塗仕上で腰を下見板張。北・東面に各１箇所戸口を設け、各階板敷で上部に和小屋を現す。敷地外郭を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015174"},{"id":"00015178","register_sub_id":"101","register_pk":"530602","name":"西野百助家住宅北門及び北塀","kana":"にしのひゃくすけけじゅうたくきたもんおよびきたべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市定友町9字辻堂2他","lat":35.91431111,"lng":136.24620556,"geo_status":"db","era":"昭和2年頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"北門 木造、銅板葺、間口1.6m 北塀 木造、銅板葺、総延長45m","structure_material":"北門 木造","registered":"2024.12.03(令和6.12.03)","register_no":"18 - 0248","desc":"主屋の北にある北門と敷地北辺を折れ曲がり、離れに至る北塀。東面して建つ北門は一間の腕木門で、門口に引違板戸を建てる。北塀は総延長４５メートルの板塀で、柱間を貫で固め、壁を竪板張とし、屋根は銅板葺。北門と一体で敷地北辺の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015178"},{"id":"00015177","register_sub_id":"101","register_pk":"530601","name":"西野百助家住宅庭門及び南塀","kana":"にしのひゃくすけけじゅうたくにわもんおよびみなみべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市定友町9字辻堂1他","lat":35.91403611,"lng":136.24604444,"geo_status":"db","era":"昭和2年頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"庭門 木造、瓦葺、間口2.1m 南塀 木造、瓦葺、総延長61m","structure_material":"庭門 木造","registered":"2024.12.03(令和6.12.03)","register_no":"18 - 0247","desc":"主屋南側にある庭門と敷地東南辺に建ち南土蔵に至る南塀。通りに東面する庭門は一間の腕木門。切妻造桟瓦葺で大棟を高く積む。南塀は総延長６１メートルの塀。亀甲切石積上に建ち、外壁は漆喰塗で簓子下見板を高く張る。庭門と一体で旧家の屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015177"},{"id":"00015176","register_sub_id":"101","register_pk":"530600","name":"西野百助家住宅離れ","kana":"にしのひゃくすけけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市定友町9字辻堂2他","lat":35.91439722,"lng":136.24603611,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡、東門附属","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"18 - 0246","desc":"北土蔵の東に位置し、亀甲積石垣上に建つ離れ。入母屋造桟瓦葺の東西棟で、東・南面に下屋を付す。内部の６畳は西に床と窓付の床脇を備え、北に腰壁付窓を開ける。長押・竿・天井板・床柱など素木、軸部は透漆塗、天井廻縁は黒漆塗として塗分けた上質な離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015176"},{"id":"00015175","register_sub_id":"101","register_pk":"530599","name":"西野百助家住宅南土蔵","kana":"にしのひゃくすけけじゅうたくみなみどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市定友町9字辻堂2他","lat":35.91425278,"lng":136.24596111,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積83㎡","structure_material":"土蔵造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"18 - 0245","desc":"北土蔵の南に連続して建つ家財蔵。２階建切妻造の南北棟で、東・南面に北土蔵から一連の吹放ち下屋を付す。外壁は漆喰塗仕上で軒に鉢巻を廻らす。東・南面に各一箇所戸口を設け、内部は各階板敷で上部に和小屋を現す。北土蔵とともに長大な土蔵景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015175"},{"id":"00013727","register_sub_id":"101","register_pk":"505261","name":"馬場家住宅主屋","kana":"ばばけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市広瀬町92字辻8","lat":35.88733611,"lng":136.13281389,"geo_status":"db","era":"明治24年頃／明治39年増築改修、昭和前期増築","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階建、瓦葺、建築面積245㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 229","desc":"越前市街地西方に位置し、敷地中央に南面する。南北棟の二階建切妻造桟瓦葺の主体部の西に角屋を伸ばして玄関とし、周囲に下屋を付す。主体部南半に台所、北半に五室を配し、庭に臨む東側に座敷を配す。束と貫を整然と重ねた妻面をみせる越前の豪壮な民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013727"},{"id":"00013728","register_sub_id":"101","register_pk":"505263","name":"馬場家住宅土蔵","kana":"ばばけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市広瀬町92字辻8","lat":35.88750556,"lng":136.13262222,"geo_status":"db","era":"明治25年","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、瓦葺、建築面積56㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 230","desc":"敷地北西隅に建つ土蔵。桁行四間半、梁間三間、二階建切妻造平入桟瓦葺の東西棟で、南面東寄りを戸口とし下屋を付す。腰高に切石積基礎を積み、外壁は漆喰塗で軒まで塗込め、下部を下見板張とする。戸口廻りは漆喰塗で柱や楣を造り出し、特に意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013728"},{"id":"00013729","register_sub_id":"101","register_pk":"505265","name":"馬場家住宅長屋門","kana":"ばばけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県越前市広瀬町92字辻8","lat":35.88711667,"lng":136.13265278,"geo_status":"db","era":"文久2年(1862)／大正2年移築","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 231","desc":"主屋の南西に南面して建つ。桁行六間半梁間二間半の東西棟の入母屋造平入桟瓦葺の北西に桁行二間梁間二間の突出部を持ち、全体としてＬ字形の平面とする。南面中央二間を門口とし、両開の板戸を吊って両脇にそれぞれ潜戸を設ける。旧家の風格を示す長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013729"},{"id":"00009595","register_sub_id":"101","register_pk":"194591","name":"藤野厳九郎記念館(旧藤野家住宅主屋)","kana":"ふじのげんくろうきねんかん（きゅうふじのけじゅうたくしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県あわら市温泉1-203-1","lat":36.22380515,"lng":136.19328323,"geo_status":"db","era":"昭和初期／昭和58・平成23移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積61㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"18 － 0117","desc":"あわら温泉湯のまち広場の東側に南面して建つ。木造二階建、切妻造妻入、桟瓦葺で、南面及び東面に下屋を廻らす。外壁のほか、窓の外側も腰高に簓子下見板を張り寒風対策を講じる。室構成などに日本海沿いの旧三国町における町家形式を伝える、近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009595"},{"id":"00006748","register_sub_id":"101","register_pk":"107731","name":"都菓子舗土蔵","kana":"みやこかしほどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県小浜市小浜鹿島41","lat":35.49305,"lng":135.738708,"geo_status":"db","era":"明治中期／大正後期曳家","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積14㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"18 － 0055","desc":"作業場の北方、敷地最奧に位置し、南北棟で建つ。桁行２間半、梁間２間の規模で、切妻造妻入桟瓦葺の２階建土蔵で、南面に戸口を設け、２階に庇付の窓をあける。小屋組は地棟に登梁を架ける。外部は白漆喰塗で、窓及び出入口の扉は掛子塗とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006748"},{"id":"00013341","register_sub_id":"101","register_pk":"367967","name":"村松兵助家住宅主屋","kana":"むらまつひょうすけけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県大飯郡おおい町本郷120字古川4-1","lat":35.47878889,"lng":135.62321667,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積185㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"18 － 0195","desc":"旧丹後街道沿いの商家で、主屋は街道に西面して建つ。間口の広い切妻造の平屋建で、正面は出桁造として両端に袖壁を出し、全面に下屋を通す。南に土間を取る整形四間取で、北端に玄関を開いて奥に仏間と座敷を連ねる。街道の歴史的景観の核をなす大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013341"},{"id":"00013342","register_sub_id":"101","register_pk":"367968","name":"村松兵助家住宅土蔵","kana":"むらまつひょうすけけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県大飯郡おおい町本郷120字古川4-1","lat":35.4786,"lng":135.62324167,"geo_status":"db","era":"明治後期／大正前期増築、昭和60年頃改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建及び平屋建、瓦葺、建築面積152㎡","structure_material":"土蔵造2階建及び平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"18 － 0196","desc":"敷地北端に南面して建ち、西妻を街道に面する。平屋建の東土蔵と二階建の西土蔵からなり、正面に下屋を通して蔵前とする。屋根は東西棟の切妻造段違い、小屋組はトラス、内部は西土蔵が板敷、東土蔵が土間である。伝統的な商家の屋敷構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013342"},{"id":"00006684","register_sub_id":"101","register_pk":"107667","name":"森下家住宅主屋","kana":"もりしたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県小浜市小浜今宮87他","lat":35.497116,"lng":135.74292,"geo_status":"db","era":"明治後期／昭和前期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積222㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"18 － 0059","desc":"旧下市場町の通りに西面する。正面７間半、２階建の町家。表構えは主体部と付属屋からなり、出桁造で、袖壁を設け、木部を弁柄塗とする。内部は一体的に使われ、正面に広い土間のミセ、奥に床上を設ける。旧小浜城下における近代町家の一例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006684"},{"id":"00015305","register_sub_id":"101","register_pk":"532429","name":"湯浅家住宅主屋","kana":"ゆあさけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県大飯郡高浜町宮崎45字西宮崎10","lat":35.48983611,"lng":135.55386389,"geo_status":"db","era":"明治25年／昭和57年・平成6年改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、瓦葺、建築面積178㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"18 - 0257","desc":"高浜市街地東部にある旧家の主屋。通りに東面するつし２階建切妻造平入桟瓦葺。外壁漆喰塗で軒は出桁造とし両脇に袖壁を付す。一階は南に土間、北に部屋を並べ、北西に座敷を配す。下屋は軒を漆喰で塗込め、軒先に土戸を吊る金具を残すなど防火に厳重な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015305"},{"id":"00015308","register_sub_id":"101","register_pk":"532432","name":"湯浅家住宅米蔵","kana":"ゆあさけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県大飯郡高浜町宮崎45字西宮崎10","lat":35.49002222,"lng":135.55358333,"geo_status":"db","era":"安政2年（1855）／昭和8年移築","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"18 - 0260","desc":"宝蔵の西に続く米蔵。２階建切妻造妻入桟瓦葺で外壁漆喰塗仕上、焼杉竪板を軒まで張る。北妻に戸口を開け、内部は各階一室の板敷で、北東隅に階段を配す。二階上部は二重梁上の地棟に束を立て棟木を支持。窓小さく閉鎖的な外観で、敷地内最古の貴重な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015308"},{"id":"00015306","register_sub_id":"101","register_pk":"532430","name":"湯浅家住宅新座敷","kana":"ゆあさけじゅうたくしんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県大飯郡高浜町宮崎45字西宮崎10","lat":35.48997222,"lng":135.55381111,"geo_status":"db","era":"昭和8年／昭和10年代増築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積138㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"18 - 0258","desc":"主屋北西に接続する座敷棟。平屋建入母屋造桟瓦葺の東西棟で北西に浴室と便所を延ばす。内部は廊下の東に式台玄関と応接室、西に３室の続き間座敷を配す。応接間は全体に洋風意匠としつつ北面には床を構え、細部に至るまで凝ったつくりの上質な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015306"},{"id":"00015307","register_sub_id":"101","register_pk":"532431","name":"湯浅家住宅宝蔵","kana":"ゆあさけじゅうたくほうぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県大飯郡高浜町宮崎45字西宮崎10","lat":35.49,"lng":135.55368056,"geo_status":"db","era":"明治14年／昭和8年移築","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積52㎡","structure_material":"土蔵造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"18 - 0259","desc":"新座敷の西に位置する家財蔵。二階建切妻造平入桟瓦葺で南中央に戸口を開け、下屋を付して蔵前とし、東寄りの屋根を切上げ玄関とする。外壁漆喰塗仕上で二階正面に窓を開ける。各階板敷で小屋組は登梁と水平梁の併用。新座敷と一連で敷地北西の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015307"},{"id":"00009268","register_sub_id":"101","register_pk":"194061","name":"吉崎御坊蓮如上人記念館七不思議堂主屋","kana":"よしざきごぼうれんにょしょうにんきねんかんななふしぎどうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県あわら市吉崎1-902-1","lat":36.28932619,"lng":136.25123744,"geo_status":"db","era":"明治14年／昭和54年移築","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋一部2階建、瓦葺一部銅板葺、建築面積337㎡","structure_material":"木造平屋一部2階建","registered":"2012.08.13(平成24.08.13)","register_no":"18 － 0111","desc":"北潟湖に面する敷地中央に東面し、木造平屋一部二階建、建築面積三三七平方メートル、切妻造妻入桟瓦葺で、周囲に下屋を廻らす。重厚な架構をもつ二八畳の広間を中心に上質なつくりの座敷を配する。アズマダチと称される越中型民家の特徴を示す大型建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009268"},{"id":"00014356","register_sub_id":"101","register_pk":"511345","name":"吉田家住宅（旧東小林家住宅）主屋","kana":"よしだけじゅうたく（きゅうひがしこばやしけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市岩本町17字内代12-1他","lat":35.90799722,"lng":136.24931389,"geo_status":"db","era":"明治前期／昭和４年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積81㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"18 - 0233","desc":"越前和紙産地の岩本町に所在する在郷商家の主屋。敷地中央に西面する二階建切妻造平入桟瓦葺で、西面南を戸口とする。一階は四室で東南室で座敷棟に接続し、二階は東半を座敷とする。越前地方民家の定型に近い造りで、和紙で栄えた地域の歴史を伝える主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014356"},{"id":"00014357","register_sub_id":"101","register_pk":"511346","name":"吉田家住宅（旧東小林家住宅）座敷棟","kana":"よしだけじゅうたく（きゅうひがしこばやしけじゅうたく）ざしきとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"福井県","address":"福井県越前市岩本町17字内代12-1他","lat":35.90795833,"lng":136.24941389,"geo_status":"db","era":"江戸末期／昭和10年増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積59㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"18 - 0234","desc":"在郷商家の主屋の東側に接続する座敷棟。平屋建切妻造妻入桟瓦葺で、内部は西面南寄りに設けた式台から仏間を抜けて座敷に至る。座敷は東面に床の間を構え、南北二面に縁を付す。座敷は長押を廻さず、簡素ながらも柱や天井を漆塗で仕上げた華やかな座敷棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014357"},{"id":"00012146","register_sub_id":"101","register_pk":"352945","name":"若狭国吉城歴史資料館（旧田辺半太夫家住宅）","kana":"わかさくによしじょうれきししりょうかん（きゅうたなべはんだいけじゅうたく）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"福井県","address":"福井県三方郡美浜町佐柿25-2","lat":35.61083,"lng":135.963642,"geo_status":"db","era":"江戸後期／平成21年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積259㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"18-186","desc":"切妻造の主屋部と入母屋造の座敷部を並べる。主屋部は、資料館のため内部を改修しているが、一尺角の大黒柱や軸部をよく残し、豪壮な梁組を現しとする。座敷部は式台玄関を設け、八畳の座敷二室を配す。赤土壁が特徴的で、細部に数寄屋風意匠を加味した座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012146"},{"id":"00011301","register_sub_id":"101","register_pk":"209138","name":"相原家住宅主屋","kana":"あいはらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲府市御岳町2472","lat":35.767443,"lng":138.556598,"geo_status":"db","era":"明治後期／昭和27頃・同61改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、鉄板葺、建築面積203㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"19－0085","desc":"金櫻神社門前に建つ住居兼宿泊施設。木造二階建で、道路に平側を見せる東西棟部分に玄関を設け、内部には土間を広くとる。小屋はトラス組とし、二階は五○畳敷の大広間とする。南北棟部分は一階を住居、二階を客間も兼ねた座敷とする。地域に残る希少な講中宿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011301"},{"id":"00016506","register_sub_id":"101","register_pk":"574868","name":"秋山家住宅（菊谷坊）板蔵","kana":"あきやまけじゅうたく（きくやぼう）いたくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県富士吉田市上吉田五丁目609","lat":35.47696083,"lng":138.79762278,"geo_status":"db","era":"明治４１年／昭和中期増築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"19 - 0198","desc":"主屋の北西に位置する道具蔵。東面して建つ平屋建切妻造平入瓦棒鉄板葺の板蔵で、北と東に下屋を付し、北は物置、東は戸前とする。内部は一室の板敷とし、西側に中二階を設け、南面に窓を一箇所開ける。小屋は垂木構造。主屋とともに御師住宅の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016506"},{"id":"00016505","register_sub_id":"101","register_pk":"574867","name":"秋山家住宅（菊谷坊）主屋","kana":"あきやまけじゅうたく（きくやぼう）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県富士吉田市上吉田五丁目609","lat":35.47696083,"lng":138.79762278,"geo_status":"db","era":"江戸末期／大正9年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、鉄板葺、建築面積246㎡","structure_material":"木造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"19 - 0197","desc":"上吉田の南東部に位置する御師住宅の主屋。タツミチを東へ入り、二階建寄棟造平入鉄板葺を西面して建て、北西に台所、南東に広縁を介し御神前を配す。各階六室で西面中央に式台玄関を設け、南西に続き間座敷を配す。御神前など御師住宅の様相を伝える主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016505"},{"id":"00006841","register_sub_id":"101","register_pk":"107823","name":"芦澤家住宅座敷蔵","kana":"あしざわけじゅうたくざしきぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県南アルプス市西野97-1","lat":35.64046421,"lng":138.482605,"geo_status":"db","era":"昭和8頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"19 － 0060","desc":"主屋座敷の西面に蔵前で接続して建つ。桁行８．０ｍ梁間４．５ｍ、切妻造妻入桟瓦葺、２階建。外壁は漆喰塗、腰をモルタル塗とする。トコ等をもつ接客用の蔵座敷があったが、主屋再建時に居室等に変更。主屋と座敷蔵が並び立つ屋敷景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006841"},{"id":"00006840","register_sub_id":"101","register_pk":"107822","name":"芦澤家住宅主屋","kana":"あしざわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県南アルプス市西野97-1","lat":35.64041111,"lng":138.48272224,"geo_status":"db","era":"昭和8／平成16改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積167㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"19 － 0059","desc":"通りから北奥に入った、敷地中央に東西棟で建つ。桁行６間梁間４間、つし２階建、切妻造桟瓦葺の上屋に、四周下屋をまわし、正面に後補の入母屋造妻入の玄関を付設する。太い胴差など重厚な軸組のなか、繊細瀟洒な建具など軽快な造作がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006840"},{"id":"00008857","register_sub_id":"101","register_pk":"162300","name":"飯島家住宅旧土蔵","kana":"いいじまけじゅうたくきゅうどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲州市塩山上於曽1264","lat":35.7079654,"lng":138.73035013,"geo_status":"db","era":"明治前期／昭和中期・後期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、鉄板葺、建築面積40㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"19 － 0064","desc":"旧塩山市街地に位置し、本町通りに西面する。桁行８．７ｍ梁間４．６ｍ、木造二階建、切妻造鉄板葺。通り側は一・二階とも大きく開き、軒及び側・背面は塗り込める。一階内部は広い一室で、中央後方に板床を設ける。土蔵の面影を留める店舗建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008857"},{"id":"00008858","register_sub_id":"101","register_pk":"162301","name":"飯島家住宅長屋門","kana":"いいじまけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県甲州市塩山上於曽1264","lat":35.70785664,"lng":138.73024963,"geo_status":"db","era":"江戸末期／昭和前期・昭和58年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、鉄板葺、建築面積116㎡","structure_material":"木造平屋一部2階建","registered":"2011.10.28(平成23.10.28)","register_no":"19 － 0065","desc":"旧土蔵の南に位置する。中央に表門を開き、北に二階屋の旧店舗、南に物置を配する。木造で、建築面積１１６㎡。表門と物置は一連の屋根で、旧店舗とともに切妻造鉄板葺。いずれも出桁造とし、一軒疎垂木とする。風格ある表構えが街道景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008858"},{"id":"00004755","register_sub_id":"101","register_pk":"105745","name":"井出家住宅主屋","kana":"いでけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南都留郡富士河口湖町船津字宮ノ森20-1","lat":35.50229128,"lng":138.76606642,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺、建築面積150㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"19 － 0054","desc":"宅地中央に南面する。桁行１１間半，梁間５間，２階建，切妻造，鉄板葺で，４周に下屋を廻し正面西寄りに玄関を突出する。土間部分とその西の６間取床上部からなる民家で，もと石置板葺の緩勾配の屋根と深い軒による外観をもち，周囲の歴史的景観の核となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004755"},{"id":"00014804","register_sub_id":"101","register_pk":"519062","name":"大鴈丸家住宅主屋","kana":"おおがんまるけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県富士吉田市上吉田七丁目636","lat":35.47604444,"lng":138.79363333,"geo_status":"db","era":"明治前期／平成28年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、鉄板葺、建築面積286㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"19 - 0175","desc":"上吉田の南東部に位置する御師住宅の主屋。タツミチを東へ入って、平屋建切妻造平入鉄板葺の主屋を西面して建て、北西に角屋の台所を延ばし、全体にＬ字を呈する。西面中央に式台玄関を設け、その奥の座敷は床・棚・付書院を備え、富士講宿泊の様相を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014804"},{"id":"00013247","register_sub_id":"101","register_pk":"366236","name":"大村家住宅主屋","kana":"おおむらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県韮崎市神山町鍋山字上小路1880-1","lat":35.70124722,"lng":138.42786667,"geo_status":"db","era":"明治40年頃／平成2年頃改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積137㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"19 － 0146","desc":"市内中央、釜無川右岸の平野部に位置し、敷地の北西に南面して建つ。木造平屋建、切妻造桟瓦葺で、外壁は白漆喰塗。内部は東側に土間、西側に土間に沿って板間が二室、さらに奥にそれぞれ南北二室の六畳間と八畳間が並ぶ。当地域の近世農家住宅の伝統を継ぐ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013247"},{"id":"00013248","register_sub_id":"101","register_pk":"366237","name":"大村家住宅土蔵","kana":"おおむらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県韮崎市神山町鍋山字上小路1880-1","lat":35.70131389,"lng":138.42802222,"geo_status":"db","era":"大正5年頃／昭和30年代増築、昭和20年頃・平成2年頃改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積73㎡","structure_material":"土蔵造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"19 － 0147","desc":"主屋の東側に西面して建つ。土蔵造二階建、切妻造桟瓦葺平入で、北面の一部と西面に下屋を付す。一階は南から書庫と倉庫を配し、二階は西側に廊下を通し、南から八畳間二室、四畳間を並べる。東面は敷地東端の石垣上に建ち、農村集落の景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013248"},{"id":"00011492","register_sub_id":"101","register_pk":"210455","name":"御北穂坂家住宅主屋","kana":"おきたほさかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県南アルプス市高尾字北畑537-1","lat":35.62096889,"lng":138.40700389,"geo_status":"db","era":"明治24年頃","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造平屋一部2階建、茅葺（鉄板仮葺）、建築面積248㎡","structure_material":"木造平屋一部2階建","registered":"2017.05.02(平成29.05.02)","register_no":"19-0087","desc":"桁行一二間梁間四間半の規模で、東妻を入母屋、西妻を切妻とする。正面側屋根中央部には突上げのアカリトリを設ける。かつては茅葺で正面切庇を設けず葺き下ろしていた。床上部正面側は奥から一二畳座敷、一二畳、八畳を連ねる。養蚕にも用いられた大規模農家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011492"},{"id":"00012733","register_sub_id":"101","register_pk":"367636","name":"小沢家住宅主屋","kana":"おざわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲州市勝沼町等々力1372他","lat":35.66644778,"lng":138.71209083,"geo_status":"db","era":"明治中期／大正3年頃・昭和61年頃改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階一部3階建、瓦葺、建築面積287㎡","structure_material":"木造2階一部3階建","registered":"2019.03.29(平成31.03.29)","register_no":"19 － 137","desc":"旧甲州街道沿いの養蚕農家。主屋は前庭に南面して建つ入母屋造桟瓦葺の総二階建で、四周に下屋を廻し、棟中央に越屋根を付す。東に土間、西の前後に各3室を配して上手に座敷2室を並べ、二階は蚕室とする。養蚕で栄えた近代山梨の農家主屋の形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012733"},{"id":"00012734","register_sub_id":"101","register_pk":"367637","name":"小沢家住宅文庫蔵","kana":"おざわけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲州市勝沼町等々力1372他","lat":35.66644778,"lng":138.71209083,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"19 － 138","desc":"主屋背面の西側に東面して建つ。土蔵造二階建、切妻造桟瓦葺で、正面中央に扉口を設け、下屋を蔵前として主屋と接続する。外壁は漆喰塗の腰黒漆喰で、軒に鉢巻を廻す。内部は上下階とも板敷、小屋組は登梁とする。上層農家の伝統的な屋敷構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012734"},{"id":"00011493","register_sub_id":"101","register_pk":"210456","name":"御西穂坂家住宅主屋","kana":"おにしほさかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南アルプス市高尾436","lat":35.62086,"lng":138.40665,"geo_status":"db","era":"弘化3年（1846）頃","year":1846,"year_source":"db","year_min":1846,"year_max":1846,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積189㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"19-0088","desc":"近隣の穂見神社の神主を務めた家で、木造平屋建、切妻造茅葺（鉄板仮葺）とする。桁行一一間、梁間五間の規模で、東に土間を取り、西寄り床上部は六室とする。南西隅の座敷以外は根太天井とし、天井裏を養蚕に用いていたが、全体に建ちが低いのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011493"},{"id":"00004751","register_sub_id":"101","register_pk":"105741","name":"風間酒造主屋","kana":"かざましゅぞうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲州市塩山下於曽910","lat":35.69728093,"lng":138.72700428,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積238㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"19 － 0050","desc":"造り酒屋の主屋で敷地中央に南面する。桁行１２間，梁間６間，２階建，入母屋造，桟瓦葺で，東３分の１を土間，その西を床上部とし，１，２階とも座敷を多数配す。当地方独特の民家形式を踏襲した大規模な建物で，たちが高く通りに大妻面を見せて威容を誇る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004751"},{"id":"00004754","register_sub_id":"101","register_pk":"105744","name":"風間酒造文庫蔵","kana":"かざましゅぞうぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲州市塩山下於曽910","lat":35.69739421,"lng":138.72699952,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"19 － 0053","desc":"主屋と酒造蔵の間に建つ。桁行５間，梁間３間，土蔵造，２階建，切妻造，桟瓦葺で，出入口を開く東面に大きく下屋を付け座敷２室を配する。扉や窓廻りを入念に仕上げ，軒裏を大きく斜めに塗り上げ高い大棟による重厚な外観をもち，屋敷構えに欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004754"},{"id":"00013992","register_sub_id":"101","register_pk":"508252","name":"金丸家住宅土蔵","kana":"かねまるけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県南アルプス市小笠原字二丁目西319-1","lat":35.60838056,"lng":138.46672222,"geo_status":"db","era":"明治33年／平成7年・同17年改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積50㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"19 - 0164","desc":"駿信往還の小笠原宿に所在する。土蔵造二階建、切妻造桟瓦葺。壁は漆喰仕上に水切二段を付し、道路に面した壁は腰を洗出仕上とする。南面に戸口を設け、内部は一階は二室で台所等に改装した。二階も二室で西は一五畳和室。旧宿場町の景観を形成する座敷蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013992"},{"id":"00016507","register_sub_id":"101","register_pk":"574869","name":"旧上田家住宅主屋","kana":"きゅううえだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県南アルプス市中野字上杉木316他","lat":35.60180778,"lng":138.43486083,"geo_status":"db","era":"明治前期／昭和46年・令和5年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋一部2階建、瓦葺一部鉄板葺、建築面積144㎡","structure_material":"木造平屋一部2階建","registered":"2026.02.10(令和8.02.10)","register_no":"19 - 0199","desc":"市街西方の山麓の敷地に南面して建つ。切妻造平入桟瓦葺で南西北面に下屋を設ける。平面は右土間形式で前後二列に八畳三室を並べ、前列上手の座敷は長押を廻らし床と付書院を設える。前面下屋は広縁とする。当地の伝統的な民家形式の発展を伝える大型住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016507"},{"id":"00016508","register_sub_id":"101","register_pk":"574870","name":"旧上田家住宅土蔵","kana":"きゅううえだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県南アルプス市中野字上杉木316他","lat":35.60180778,"lng":138.43486083,"geo_status":"db","era":"明治26年","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"19 - 0200","desc":"主屋西側に南北棟で建つ。桁行三間梁間二間、土蔵造二階建切妻造桟瓦葺。外壁中塗仕上で東・北面の腰は鼠漆喰仕上で下屋を付す。一階東面中央の戸口に漆喰塗の鳥居枠をつくり、二階南妻に窓を開く。小屋組は梁上の束で棟木を受ける。集落景観に寄与する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016508"},{"id":"00003231","register_sub_id":"101","register_pk":"104221","name":"旧富岡敬明家住宅厩","kana":"きゅうとみおかけいめいけじゅうたくうまや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県甲府市善光寺町3135","lat":35.673096,"lng":138.595551,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積50㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"19 － 0046","desc":"蔵の南方，一段低い平地に東西棟で建つ。桁行７間半梁間２間の細長の平面をもつ。もと茅葺，寄棟造，平屋建の馬小屋で，東方桁行３間半分を厩，西方を８畳と６畳の居室とする。蔵とともに屋敷地頭部の主要素になり，屋敷南正面に欠くことのできない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003231"},{"id":"00003230","register_sub_id":"101","register_pk":"104220","name":"旧富岡敬明家住宅蔵","kana":"きゅうとみおかけいめいけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲府市善光寺町3135","lat":35.673183,"lng":138.595535,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"19 － 0045","desc":"甲府駅の東北方，善光寺町の緩斜面地に位置する富岡家住宅主屋部の東南方に東西棟で建つ。桁行４間梁間２間規模，桟瓦葺，切妻造の平入２階建土蔵で，北面に入口を設け，北面及び西面に土庇を差掛ける。貴族院議員辞職後の屋敷構えを形成する主要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003230"},{"id":"00003232","register_sub_id":"101","register_pk":"104222","name":"旧富岡敬明家住宅石塁","kana":"きゅうとみおかけいめいけじゅうたくせきるい","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県甲府市善光寺町3135","lat":35.67337574,"lng":138.5950047,"geo_status":"db","era":"明治8頃","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"石造、延長30m","structure_material":"石造","registered":"2003.03.18(平成15.03.18)","register_no":"19 － 0047","desc":"屋敷地西方を南北に流れる高倉川の氾濫時の土石流から主屋を防御する目的も兼ねて築造。主屋の北方から西方にかけて，玉石あるいは割石積みの高さ１．３～１．５ｍ，幅１～２ｍ程の石堤や高さ１ｍ程の石垣を要所に配置する。宅地の造成経緯を知るうえで貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003232"},{"id":"00006708","register_sub_id":"101","register_pk":"107691","name":"旧根津家住宅主屋","kana":"きゅうねづけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県山梨市正徳寺字柳田296他","lat":35.678795,"lng":138.66825607,"geo_status":"db","era":"昭和8／平成18改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積292㎡、地下室付","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"19 － 0056","desc":"木造２階建を中心に事務室や台所などの棟からなる。主体部は１、２階とも座敷３室が１列に並び、最奥室にトコ等を設ける。屋根は起りのある桟瓦葺屋根で、軒まわりを銅板葺とする。外壁は黄漆喰仕上げ。平書院の瀟洒な建具など、洗練された意匠の近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006708"},{"id":"00006709","register_sub_id":"101","register_pk":"107692","name":"旧根津家住宅土蔵","kana":"きゅうねづけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県山梨市正徳寺字柳田296他","lat":35.67882333,"lng":138.66846333,"geo_status":"db","era":"昭和8頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積64㎡","structure_material":"土蔵造3階建","registered":"2007.12.05(平成19.12.05)","register_no":"19 － 0057","desc":"桁行４間半梁間２間の蔵前を介して主屋と接続する３階建土蔵で、切妻造桟瓦葺の置屋根とする。外壁は白漆喰塗で、腰を海鼠壁とし、黄漆喰仕上げの蔵前と鮮やかな対照をみせる。２段に水切りを設け、妻側は各階に庇付窓を開け、リズム感のある外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006709"},{"id":"00006710","register_sub_id":"101","register_pk":"107693","name":"旧根津家住宅長屋門","kana":"きゅうねづけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県山梨市正徳寺字柳田296他","lat":35.678867,"lng":138.66779807,"geo_status":"db","era":"昭和初期／平成17改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積137㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"19 － 0058","desc":"旧青梅街道に面して建つ。北西を正面とする桁行１６間梁間３間の規模。屋根は起りのある寄棟造桟瓦葺。中央３間を通路とし持送りを数多く設け装飾的にする。通路両側に各桁行６間半の部屋を造り、それぞれ正面２ヶ所に庇付出格子を設け、対称的な外観に造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006710"},{"id":"00015312","register_sub_id":"101","register_pk":"532436","name":"旧宮下家住宅（柏屋）米蔵","kana":"きゅうみやしたけじゅうたく（かしわや）こめくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県富士吉田市上吉田四丁目264","lat":35.4798,"lng":138.794825,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、鉄板葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"19 - 0185","desc":"上吉田の中央西側に位置し、かつて雑貨商を営んだ商家の米蔵。敷地西寄りに建つ、二階建切妻造平入、置屋根形式の鉄板葺で外壁漆喰塗仕上。東に戸口を開けて下屋を付す。各階一室の板敷で、内壁は板を積んだいわゆる井籠蔵。戸口の掛子塗扉など丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015312"},{"id":"00012902","register_sub_id":"101","register_pk":"368005","name":"旧森家住宅主屋","kana":"きゅうもりけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県山梨市落合288-2","lat":35.68151667,"lng":138.66091111,"geo_status":"db","era":"大正8年／平成30年改修","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積245㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"19 － 139","desc":"市街地近郷にある民家。敷地中央北寄りに南面して建ち、切妻造の主体部に入母屋造の座敷部をＬ字形に連ねる。主体部は東側土間、西側二列四室の伝統的な平面で、座敷部は続き間に式台玄関を備えるなど格式高くつくる。峡東地域民家の近代的な展開を示す一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012902"},{"id":"00014810","register_sub_id":"101","register_pk":"519068","name":"迎賓館えびす屋（旧望月家住宅主屋）","kana":"げいひんかんえびすや（きゅうもちづきけじゅうたくおもや）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県南巨摩郡身延町身延字町方3963他","lat":35.37101111,"lng":138.42537778,"geo_status":"db","era":"昭和7年／令和2年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積225㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"19 - 0181","desc":"久遠寺の門内に位置する旧家の洋館付き和風住宅。敷地中央に建つ平屋建桟瓦葺で、中廊下を矩折れに延ばし、南に2室の洋室、西に続き間座敷で北西に床を構える。座敷は西と南に縁を廻らしガラス戸を建て、洋館は西に出窓を開けて、庭園を望む近代和風の住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014810"},{"id":"00015311","register_sub_id":"101","register_pk":"532435","name":"小澤家住宅主屋","kana":"こざわけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県富士吉田市上吉田六丁目132","lat":35.47693889,"lng":138.79221389,"geo_status":"db","era":"明治前期／昭和中期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋一部2階建、鉄板葺、建築面積234㎡","structure_material":"木造平屋一部2階建","registered":"2025.03.13(令和7.03.13)","register_no":"19 - 0184","desc":"上吉田の南西部に位置する御師住宅の主屋。タツミチの西に東面して建つ平屋建切妻造妻入鉄板葺。北に土間と台所、南に三列部屋を並べ、西中央に玄関を構える。南西の主座敷は床・棚・菱格子欄間の付書院を備える。間取りなど御師住宅の様相をよく留める主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015311"},{"id":"00008860","register_sub_id":"101","register_pk":"162303","name":"西湖いやしの里根場旧渡辺家住宅主屋","kana":"さいこいやしのさとねんばきゅうわたなべけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南都留郡富士河口湖町西湖字根場2753","lat":35.50539981,"lng":138.66093226,"geo_status":"db","era":"江戸末期／明治後期・平成20年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"19 － 0067","desc":"緩やかな傾斜地に南面して建つ。屋根を兜造風とする茅葺の養蚕家屋で、棟は芝棟とする。正面１４ｍ奥行７．９ｍで、東端前方を土間、後方を板間、中央を板間の広間、西端を座敷とする。小屋裏は二層で、蚕室として使用された。山村に残る養蚕民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008860"},{"id":"00014598","register_sub_id":"101","register_pk":"515140","name":"櫻林家住宅奥座敷","kana":"さくらばやしけじゅうたくおくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県甲府市宮原町1299","lat":35.61306667,"lng":138.55819167,"geo_status":"db","era":"明治45年／昭和42年増築","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、瓦葺、建築面積130㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"19 - 0167","desc":"鎌田川東岸の宮原に所在する医家の座敷棟。二階建入母屋造桟瓦葺の東西棟で、東に玄関と台所を増築し、北に便所棟を附属する。内部は各階西辺を床構えとした三間続きの座敷とし、組子の欄間や銘木を用いた繊細な造り。医家屋敷における上質な近代和風の座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014598"},{"id":"00014601","register_sub_id":"101","register_pk":"515143","name":"櫻林家住宅米蔵及び道具蔵","kana":"さくらばやしけじゅうたくこめぐらおよびどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県甲府市宮原町1299","lat":35.61324444,"lng":138.55830833,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋一部2階建、瓦葺、建築面積74㎡","structure_material":"土蔵造平屋一部2階建","registered":"2023.08.07(令和5.08.07)","register_no":"19 - 0170","desc":"医家の奥座敷北に位置する土蔵。切妻造平入桟瓦葺の東西棟で、南面一杯に下屋を付す。外壁は土蔵造漆喰塗仕上、腰を鼠漆喰仕上とし、北面に窓を並べる。一階は二室の板敷で、西は米蔵で吹抜とし、東は道具蔵で二階を設ける。屋敷の北方を構成する実用的な蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014601"},{"id":"00014602","register_sub_id":"101","register_pk":"515144","name":"櫻林家住宅長屋門","kana":"さくらばやしけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲府市宮原町1299","lat":35.61277222,"lng":138.558275,"geo_status":"db","era":"明治38年／平成14年改修","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積94㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"19 - 0171","desc":"医家の敷地南辺に開く長屋門。入母屋造平入桟瓦葺で、東寄りに門口を開け北に突出部を延ばし、全体にＴ字形平面となる。門口の東は一室で元は車夫の居室、西は三室とし、診療所として用いた。鏡板をケヤキの一枚板とする扉を吊り、風格ある表構えを造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014602"},{"id":"00014599","register_sub_id":"101","register_pk":"515141","name":"櫻林家住宅西文庫蔵","kana":"さくらばやしけじゅうたくにしぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲府市宮原町1299","lat":35.61309722,"lng":138.55808611,"geo_status":"db","era":"明治45年頃","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積67㎡","structure_material":"土蔵造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"19 - 0168","desc":"医家の奥座敷西に接続する家財蔵。二階建寄棟造桟瓦葺、東面の戸前は板敷で竿縁天井を張る。外壁は土蔵造モルタル塗仕上で水切三段を付し、腰を人造石研ぎ出しとする。内部は各階一室の板敷で小屋組キングポスト・トラス。屋敷の西方を構成する重厚な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014599"},{"id":"00014600","register_sub_id":"101","register_pk":"515142","name":"櫻林家住宅東文庫蔵","kana":"さくらばやしけじゅうたくひがしぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県甲府市宮原町1299","lat":35.61313333,"lng":138.55832222,"geo_status":"db","era":"江戸末期／昭和42年頃増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積43㎡","structure_material":"土蔵造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"19 - 0169","desc":"医家の奥座敷北に接続する家財蔵。煉瓦積布基礎に建つ二階建切妻造桟瓦葺の東西棟で、南面の戸前は板敷とする。外壁は土蔵造漆喰仕上で腰を鼠漆喰仕上とする。内部は各階一室の板敷で南東に階段を設ける。敷地内で最も古い建物で屋敷の歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014600"},{"id":"00011131","register_sub_id":"101","register_pk":"205238","name":"佐藤家住宅主屋","kana":"さとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県甲州市勝沼町菱山2565","lat":35.672929,"lng":138.740507,"geo_status":"db","era":"江戸後期／明治前期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、茅葺（鉄板仮葺）、建築面積148㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"19 - 0081","desc":"勝沼町菱山の西下がりの斜面に南面して建つ農家の主屋。桁行七間、梁間四間、切妻造茅葺で、屋根中央部を一段切り上げ、四方に下屋を廻らす。平面は西を土間、東を床上とする。軸部は棟通りに棟持ち柱を建てる。保存状況も良く甲州民家の典型的な姿を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011131"},{"id":"00014809","register_sub_id":"101","register_pk":"519067","name":"柴田家住宅（旧清水家住宅）土蔵","kana":"しばたけじゅうたく（きゅうしみずけじゅうたく）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県南アルプス市上野359","lat":35.60128889,"lng":138.44193056,"geo_status":"db","era":"昭和5年頃／平成30年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積65㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"19 - 0180","desc":"椿城跡南方の集落に位置する農家の土蔵。敷地東側に建つ二階建切妻造平入桟瓦葺で、北を戸口とし、北東に矩折れに下屋を付す。一階は土間で農産物を納め、二階は養蚕用で、各面に窓を開ける。下屋内には北に味噌蔵、南に外便所を設けるなど、農家らしい土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014809"},{"id":"00011949","register_sub_id":"101","register_pk":"211093","name":"上文司家住宅主屋","kana":"じょうもんじけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県富士吉田市上吉田四丁目269","lat":35.480132,"lng":138.794869,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋一部2階建、鉄板葺、建築面積127㎡","structure_material":"木造平屋一部2階建","registered":"2017.10.27(平成29.10.27)","register_no":"19-100","desc":"北口本宮富士浅間神社参道に続く通りの西にタツミチ（通路）を開き、細長い敷地奥に南北棟で建つ。切妻造平入の離れを曳家したもの。北から一〇畳三室、御神前が並び、さらに増築された一〇畳が接続し東全面に前廊下が通る。御師住宅の要素をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011949"},{"id":"00009273","register_sub_id":"101","register_pk":"194066","name":"杉浦家住宅土蔵","kana":"すぎうらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県中巨摩郡昭和町西条新田字村北850","lat":35.64052052,"lng":138.53239185,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積61㎡","structure_material":"土蔵造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"19 － 0071","desc":"敷地北辺、納屋の東側に東西棟で建ち並ぶ。土蔵造二階建、桁行一〇・九メートル梁間三・六メートル、切妻造桟瓦葺。南面に一間通りの下屋を差掛け、出入口を開ける。内部は東寄りに階段と押入を設けて東西に二分する。旧地主らしい重厚な屋敷地を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009273"},{"id":"00009274","register_sub_id":"101","register_pk":"194067","name":"杉浦家住宅納屋","kana":"すぎうらけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県中巨摩郡昭和町西条新田字村北850","lat":35.64045628,"lng":138.53221339,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積79㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"19 － 0072","desc":"敷地の北西隅に建ち、土蔵の西側に並ぶ。切妻造桟瓦葺、建築面積七九平方メートル、Ｌ字形の平面を呈する。開口部を南面に三箇所、東面に二箇所設け、内部を間仕切り、物置などに用いる。内壁は土壁に半割丸太の荷摺木を並べ、米蔵風のつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009274"},{"id":"00009272","register_sub_id":"101","register_pk":"194065","name":"杉浦家住宅屋敷蔵","kana":"すぎうらけじゅうたくやしきぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県中巨摩郡昭和町西条新田字村北850","lat":35.64035634,"lng":138.53228477,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積42㎡","structure_material":"土蔵造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"19 － 0070","desc":"主屋の北西側に建つ。土蔵造二階建、切妻造桟瓦葺、建築面積四二平方メートルで、東西両面に桟瓦葺の下屋を設ける。南面東側を主屋への廊下との出入口とする。東側から内部は一〇畳主室の東側に前室を配し、南面に押入と階段室を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009272"},{"id":"00000683","register_sub_id":"101","register_pk":"101673","name":"須田家住宅","kana":"すだけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県笛吹市四日市場1563","lat":35.63969952,"lng":138.63244975,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造２階建，瓦葺，建築面積91㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"19 － 0027","desc":"１階を下見板貼り，２階をドイツ壁としたハーフティンバー風の洋館で，水害を考慮して基礎を地盤より１２０ｃｍ程の高さにしている点に特徴がある。装飾的な避雷針や室内の漆喰レリーフなどに施主の洋館に対する思い入れが強く込められている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000683"},{"id":"00011950","register_sub_id":"101","register_pk":"211094","name":"高尾家住宅主屋（絹屋町織物市場）","kana":"たかおけじゅうたくしゅおく（きぬやまちおりものいちば）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県富士吉田市下吉田二丁目431","lat":35.49187,"lng":138.804832,"geo_status":"db","era":"大正14年／昭和13年頃増築","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積104㎡、塔屋付","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"19 - 0101","desc":"富士吉田の織物市場に建つ問屋。大正一四年建築の住居部と昭和一三年頃増築された店舗部からなる。住居部二階は増築の際に改められ、三畳大の板間を備えた良質な和室二室からなる。大正初期から昭和初期にかけて織物で隆盛を極めた時代を伝える貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011950"},{"id":"00011501","register_sub_id":"101","register_pk":"210464","name":"土屋家住宅裏門","kana":"つちやけじゅうたくうらもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲州市塩山三日市場字屋敷添3313-1","lat":35.72509,"lng":138.71559694,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口2.3m","structure_material":"木造","registered":"2017.05.02(平成29.05.02)","register_no":"19-0096","desc":"敷地の北面やや東寄りに位置する一間腕木門。間口は二・三メートルで、両開板戸を設け、屋根は桟瓦葺とする。全体に簡素な造りになるが、敷地北辺を画し、近代以降の大規模農家の有り様を示し、地域の歴史的景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011501"},{"id":"00011500","register_sub_id":"101","register_pk":"210463","name":"土屋家住宅麹蔵","kana":"つちやけじゅうたくこうじくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲州市塩山三日市場3313-1","lat":35.72486389,"lng":138.71564194,"geo_status":"db","era":"明治前期／昭和60年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造、瓦葺、建築面積22㎡","structure_material":"土蔵造","registered":"2017.05.02(平成29.05.02)","register_no":"19-0095","desc":"主屋の南東、敷地東辺の中ほどに建つ。桁行七・一メートル、梁間三・〇メートル、切妻造平屋建、桟瓦葺の小規模土蔵で、西面中央に扉口を開き、北面と東面に窓を設ける。麹製造のために建てられた蔵で、地域の大規模農家の営みを今日に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011500"},{"id":"00011499","register_sub_id":"101","register_pk":"210462","name":"土屋家住宅米蔵","kana":"つちやけじゅうたくこめくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲州市塩山三日市場3313-1","lat":35.72510694,"lng":138.71541611,"geo_status":"db","era":"明治前期／昭和60年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"19-0094","desc":"主屋の裏手に建つ、切妻造二階建、桟瓦葺で、桁行七・六メートル、梁間三・六メートルの規模で、当初は小作米を収めていたが、昭和三〇年代からは一階をブランデー製造に利用している。北面上部に窓を開いてアクセントとし、地域の歴史的景観に寄与する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011499"},{"id":"00011502","register_sub_id":"101","register_pk":"210465","name":"土屋家住宅座敷門及び塀","kana":"つちやけじゅうたくざしきもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲州市塩山三日市場字屋敷添3313-1","lat":35.72484889,"lng":138.71528889,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"座敷門 木造、瓦葺、間口1.7m 塀 土塀、瓦葺、総延長34m","structure_material":"座敷門 木造","registered":"2017.05.02(平成29.05.02)","register_no":"19-0097","desc":"主屋南面の内庭を画す塀と門。門は間口一・七メートルの棟門、塀は折れ曲り総延長三四メートルの屋根塀で、ともに桟瓦葺。塀は腰上下で色合いを変える土壁で、上部を襷桟で軽やかに見せる。主屋と併せ、質の高い近代民家の景観を形づくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011502"},{"id":"00011497","register_sub_id":"101","register_pk":"210460","name":"土屋家住宅主屋","kana":"つちやけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲州市塩山三日市場3313-1","lat":35.72490889,"lng":138.71554194,"geo_status":"db","era":"明治前期／昭和35年・同45年・平成15年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階一部3･4階建、瓦葺、建築面積232㎡","structure_material":"木造2階一部3･4階建","registered":"2017.05.02(平成29.05.02)","register_no":"19-0092","desc":"塩山から秩父に抜ける街道筋に位置する。主屋は、現当主の曽祖父が建てたと伝え、養蚕のため、二階屋根上に突き上げ屋根の三階部分と、越屋根の四階部分を重ねる外観が特徴。中央に玄関を開き、左前面側には一〇畳間を三室並べる。その北には中廊下を配す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011497"},{"id":"00011498","register_sub_id":"101","register_pk":"210461","name":"土屋家住宅文庫蔵","kana":"つちやけじゅうたくぶんこくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲州市塩山三日市場3313-1","lat":35.72504694,"lng":138.71531889,"geo_status":"db","era":"明治前期／昭和60年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋一部2階建、瓦葺、建築面積52㎡","structure_material":"土蔵造平屋一部2階建","registered":"2017.05.02(平成29.05.02)","register_no":"19-0093","desc":"主屋の北西側に渡廊下を介して建つ。土蔵造二階建、桟瓦葺で、桁行一〇メートル、梁間四・五メートル。小屋は登梁を用いる。当初は書物、布団、食器類等を収めていたが、後に北半の二階床を撤去し、ワイン醸造関係の物品を保管している。敷地景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011498"},{"id":"00014805","register_sub_id":"101","register_pk":"519063","name":"冨野家住宅主屋","kana":"とみのけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県富士吉田市上吉田四丁目277","lat":35.48044722,"lng":138.79509444,"geo_status":"db","era":"江戸後期／昭和中期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺、建築面積296㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"19 - 0176","desc":"上吉田の中央部西側に位置する御師住宅の主屋。タツミチを西へ入って、平屋建切妻造妻入鉄板葺の主屋を東面して建て、北東に旧の台所棟を付す。南東に玄関を設けて、三列に部屋を並べ、西列に座敷を配して北東に御神前を祀る。御師住宅の平面をよく残す主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014805"},{"id":"00014806","register_sub_id":"101","register_pk":"519064","name":"冨野家住宅中門","kana":"とみのけじゅうたくなかもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県富士吉田市上吉田四丁目277","lat":35.48032778,"lng":138.79523611,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造、鉄板葺、間口2.5m、南袖塀付","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"19 - 0177","desc":"主屋の東側に建つ中門は、桁行１間梁間１間切妻造鉄板葺の門で、南に袖塀を付す。本柱は五平、控柱は角柱とし、梁上に配した蟇股で棟木を支え、軒は一軒疎垂木とし、門口に両開板戸を吊る。主屋正面に建ち、簡素ながらも御師住宅の風格ある構えをつくる門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014806"},{"id":"00015310","register_sub_id":"101","register_pk":"532434","name":"萩原家住宅（旧大木家住宅）翁姿庵雪隠","kana":"はぎわらけじゅうたく（きゅうおおきけじゅうたく）おうしあんせっちん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県甲府市湯村三丁目508-1","lat":35.681125,"lng":138.55098611,"geo_status":"db","era":"明治後期／昭和23年・平成3年移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積4.1㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"19 - 0183","desc":"茶室の北に位置し、南面して建つ雪隠。寄棟造茅葺（鉄板仮葺）東西棟で、内部は東西二室に間仕切り、西は板床に大便器を据え、東は大理石張の土間床に小便器を据える。上部は天井を張らずに扇状に配った垂木をみせる。小規模ながらも上質なつくりの雪隠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015310"},{"id":"00015309","register_sub_id":"101","register_pk":"532433","name":"萩原家住宅（旧大木家住宅）翁姿庵茶室","kana":"はぎわらけじゅうたく（きゅうおおきけじゅうたく）おうしあんちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県甲府市湯村三丁目508-1","lat":35.68108611,"lng":138.55096389,"geo_status":"db","era":"江戸末期／昭和23年・平成3年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積13㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"19 - 0182","desc":"甲府市内北西部の住宅内に位置する茶室。寄棟造茅葺（鉄板仮葺）の南北棟で、西面北寄りに軒を網代編とした土庇を付す。内部北は二畳台目向板の茶室、南は板間の水屋で、室境に火灯口を開ける。煤竹の廻縁でキリ板の天井など材料吟味し、丁寧なつくりの茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015309"},{"id":"00011494","register_sub_id":"101","register_pk":"210457","name":"早川家住宅主屋","kana":"はやかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県笛吹市一宮町東新居字亀山1354","lat":35.637401,"lng":138.703464,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積236㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"19 - 0089","desc":"木造平屋建、入母屋造一部切妻造で、玄関から西寄りを内向き諸室、東寄りを座敷などを配する。東寄り南北両側には広い廊下を通し、南面東端部はサンルームとする。座敷廻りの数寄屋風意匠も質が高く、部分的に洋風意匠を取り入れた近代和風住宅の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011494"},{"id":"00011948","register_sub_id":"101","register_pk":"211092","name":"原家住宅主屋","kana":"はらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県富士吉田市上吉田六丁目162","lat":35.47758,"lng":138.792643,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、鋼板葺、建築面積199㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"19-99","desc":"御師が隆盛する明治から大正期に建てられた北口本宮富士浅間神社の門前に建つ御師住宅。タツミチ（通路）を通り、敷地奥正面に建つ。切妻造平入の背面に渡廊下で御神前が接続する構成で、御師住宅の典型的な平面形式をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011948"},{"id":"00012340","register_sub_id":"101","register_pk":"531664","name":"原茂ワイン奥蔵","kana":"はらもわいんおくのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県甲州市勝沼町勝沼小佐手小路3181-1","lat":35.66523611,"lng":138.73155278,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"19-116","desc":"もと文庫蔵で、主屋の前方西隅に建つ。土蔵造二階建、切妻造の南北棟で、東面に戸口を設ける。南面と東面に観音扉の窓を穿ち、窓庇には大振りの持送りを付ける。道路に面した敷地角にあって、伝統的な屋敷構えとともに良好な街路景観をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012340"},{"id":"00012338","register_sub_id":"101","register_pk":"531662","name":"原茂ワイン店舗兼主屋","kana":"はらもわいんてんぽけんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲州市勝沼町勝沼小佐手小路3181-1","lat":35.66510556,"lng":138.73165278,"geo_status":"db","era":"明治17年頃／平成12年改修","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造2階建、瓦葺、建築面積244㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"19-114","desc":"旧勝沼宿北方の丘陵地の敷地中央に北面して建つ。木造二階建、切妻造の東西棟。床上部は元三列構成で、前座敷と奥座敷が往時のまま残る。土間部は大黒柱や重厚な梁組をみせる。越屋根など養蚕民家の典型的な外観を保ちつつ、醸造業に転じた近代の大規模民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012338"},{"id":"00012339","register_sub_id":"101","register_pk":"531663","name":"原茂ワイン東蔵・西蔵","kana":"はらもわいんひがしのくら・にしのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県甲州市勝沼町勝沼小佐手小路3181-1","lat":35.66493056,"lng":138.73168889,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積129㎡","structure_material":"土蔵造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"19-115","desc":"店舗の背面に北面して建つ。土蔵造二階建、切妻造桟瓦葺で、北面に下屋を設ける。二階を東西に分けて東を登梁、西を和小屋とし、一階で接続する。外壁は白漆喰の腰黒漆喰仕上とし、正面戸口の楣部に意匠を凝らす。当地民家の伝統的な屋敷構えを構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012339"},{"id":"00004240","register_sub_id":"101","register_pk":"105230","name":"笛吹川芸術文庫（旧武藤酒造米蔵）","kana":"ふえふきがわげいじゅつぶんこ（きゅうむとうしゅぞうこめぐら）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"江戸","pref":"山梨県","address":"山梨県甲州市塩山藤木2007","lat":35.73064966,"lng":138.71718442,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積26㎡","structure_material":"土蔵造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"19 － 0049","desc":"主屋の北面東端に通用口を介して接続。水路の石積の上に建つ。桁行４間梁間２間の土蔵造平屋建で，切妻造，桟瓦葺の置屋根をかける。外壁は土壁で，東面と西面に戸口を設けて板戸を建て込み，東面２箇所の窓を開く。小屋梁は緩く曲がり，棟木を直に受ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004240"},{"id":"00004239","register_sub_id":"101","register_pk":"105229","name":"笛吹川芸術文庫（旧武藤酒造主屋）","kana":"ふえふきがわげいじゅつぶんこ（きゅうむとうしゅぞうしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県甲州市塩山藤木2007","lat":35.73053967,"lng":138.7170497,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積200㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"19 － 0048","desc":"桁行１２間梁間４間の２階建で，瓦葺切妻屋根に越屋根を載せ，南・西・北面に瓦葺の下屋が付く。西半は２列６室の居室，東半は土間で，東端に内蔵を持つ。外壁は土壁の大壁造とし，２階には半間毎に漆喰戸付の窓を開き，小屋裏３階とともに養蚕に用いた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004239"},{"id":"00011299","register_sub_id":"101","register_pk":"209136","name":"細田家住宅主屋","kana":"ほそだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県甲府市御岳町2362","lat":35.768506,"lng":138.556691,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、瓦葺、建築面積148㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"19－0083","desc":"金櫻神社の門前鳥居の脇に位置し、近代に増加した登山客等に対する旅館機能を併せて建てられた。木造二階建、入母屋造桟瓦葺の東西棟で、一階には住居部分を配し、二階には南北の中廊下を通して宿泊四室を配する。門前町の景観を形成する建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011299"},{"id":"00003087","register_sub_id":"101","register_pk":"104077","name":"村松家住宅厠","kana":"むらまつけじゅうたくかわや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県南アルプス市桃園615-1","lat":35.625336,"lng":138.46432243,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積5.5㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"19 － 0044","desc":"屋敷地の西方に所在した酒造場の蔵人用，あるいは店の客用の外便所で，主屋内玄関・中座敷の境に取付く内塀の南方に建つ。桁行１０尺梁間１間規模，切妻造，桟瓦葺で，腰を簓子下見とする丁寧で堅実な造作になる。当家の業務事情の一端を物語る遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003087"},{"id":"00003084","register_sub_id":"101","register_pk":"104074","name":"村松家住宅主屋","kana":"むらまつけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南アルプス市桃園615-1","lat":35.625469,"lng":138.464417,"geo_status":"db","era":"慶応1／明治初期改造","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造2階建、瓦葺、建築面積190㎡、中潜り門及び門塀付","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"19 － 0041","desc":"駿信往還に面する敷地の街道からは奥まった位置に南面して建つ。桁行９間半梁行６間規模で，東方に土間，西方上手に３列９室をとる。棟札から棟梁「若林駕蔵」脇棟梁「長澤彦右衛門」らが判明。２階開口部のアーチ形枠取は商家蔵建設に伴う曳家時の改装か。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003084"},{"id":"00003086","register_sub_id":"101","register_pk":"104076","name":"村松家住宅文庫蔵","kana":"むらまつけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県南アルプス市桃園615-1","lat":35.625565,"lng":138.464447,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"19 － 0043","desc":"主屋の北方に位置する。桁行３間半梁間２間規模，平入の２階建土蔵で，屋根は東西棟の切妻造置屋根とする。主屋仏間から北に方１間半，両下造の渡りの間を設けて蔵前を造る。のちに隠居蔵ともなる。主屋背面裏庭空間の構成要素として欠くことのできない存在","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003086"},{"id":"00011954","register_sub_id":"101","register_pk":"211098","name":"山口家住宅主屋","kana":"やまぐちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県大月市富浜町鳥沢402","lat":35.608704,"lng":139.001205,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造2階建、鋼板葺、建築面積222㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"19-105","desc":"甲州街道上鳥沢宿の問屋場。街道に北面して建つ切妻造平入二階建。一階は通り側に土間と根太天井を持つ和室二室が並び、背面側は和室三室に中廊下を挟み床の間を備える和室二室が並ぶ。二階は一室で養蚕のため増築されたもの。上鳥沢宿を代表する大規模町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011954"},{"id":"00016504","register_sub_id":"101","register_pk":"574866","name":"山梨中央銀行（旧名取家住宅）茶室水月","kana":"やまなしちゅうおうぎんこう（きゅうなとりけじゅうたく）ちゃしつすいげつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和中","pref":"山梨県","address":"山梨県甲府市中央二丁目471-1","lat":35.665095,"lng":138.57511278,"geo_status":"db","era":"昭和31年／平成7年移築","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"19 - 0196","desc":"甲府城下に位置する旧実業家の茶室。敷地奥に建ち、西半は切妻造桟瓦葺で南面に銅板葺土庇を通し、東半は東西棟の水屋とする。茶室は四畳半で北面に床を設け、細竹を棹とする棹縁天井張で南面は躙口を開き、掛込天井とする。良材を用いた上質なつくりの茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016504"},{"id":"00014240","register_sub_id":"101","register_pk":"509630","name":"山本家住宅主屋","kana":"やまもとけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"山梨県","address":"山梨県南都留郡富士河口湖町船津字大久保4157","lat":35.50131944,"lng":138.76906667,"geo_status":"db","era":"昭和29年／昭和46年増築・平成31年改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積119㎡","structure_material":"木造平屋一部2階建","registered":"2022.06.29(令和4.06.29)","register_no":"19 - 0165","desc":"河口湖南東に位置する和風住宅。南面し、平屋建片入母屋造で東に二階建切妻造を増築し、南中央に入母屋造玄関を付す。屋根は鉄板葺。内部は西に二列四室を配して南北両面に廊下を通し、北西室を床構え付座敷とする。河口湖畔に残る集落景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014240"},{"id":"00009275","register_sub_id":"101","register_pk":"194068","name":"有隣園資料館","kana":"ゆうりんえんしりょうかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県南都留郡富士河口湖町河口字広瀬2351他","lat":35.52492911,"lng":138.75919996,"geo_status":"db","era":"昭和12年／平成21年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、板葺、建築面積99㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"19 － 0073","desc":"河口湖北畔に米国人別荘として建築。木造二階建、建築面積一三三平方メートル、寄棟造板葺で、外壁はスギ皮張とする。建物中央の暖炉周りに一階は居間、食堂、台所を、二階は主寝室と三室を配し、湖側の居間南面は掃出し窓とする。湖畔の別荘建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009275"},{"id":"00006617","register_sub_id":"101","register_pk":"107600","name":"赤澤家住宅表門","kana":"あかざわけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代197-1","lat":36.56287,"lng":138.198425,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造、瓦葺、間口5.0m、潜戸及び左右袖塀付","structure_material":"木造","registered":"2007.12.05(平成19.12.05)","register_no":"20 － 0322","desc":"旧武家町の通りに北面して建つ。１間薬医門、切妻造桟瓦葺、左右に袖塀を付け、西に潜戸をたてる。妻飾は男梁上に笈形付大瓶束を立て、破風拝みに鰭付蕪懸魚を付し、要所に絵様実肘木を用いるなど装飾性を高めている。上級武家屋敷の表門の格式を受け継ぐ遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006617"},{"id":"00008455","register_sub_id":"101","register_pk":"134851","name":"秋山家住宅主屋","kana":"あきやまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県塩尻市大字宗賀字本山4915-1","lat":36.06102029,"lng":137.90117171,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、鉄板葺、建築面積98㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"20 － 0368","desc":"旧中山道本山宿に所在する。細長い敷地の東端に建つ、平入の町家。切妻造鉄板葺、桁行八・七メートル梁間一二メートルの木造二階建。二階前面を腕木で、もち出す出梁造とし、管柱をたて格子を設ける。南に通り土間、北側に二列六室を配する。良質な伝統的町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008455"},{"id":"00010301","register_sub_id":"101","register_pk":"199074","name":"亜武巣山荘","kana":"あむすさんそう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県北佐久郡軽井沢町大字軽井沢字今道沢12-8","lat":36.36165,"lng":138.643221,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建一部地階付、鉄板葺、建築面積52㎡","structure_material":"木造2階建一部地階付","registered":"2014.12.19(平成26.12.19)","register_no":"20-0478","desc":"傾斜地に建つ木造二階建地階付で、外観は三階建に見せる。切妻造鉄板葺、外壁下見板張の簡素な外観で、内部は板壁、丸太の根太天井、自然石積の暖炉など山荘風とする。低い階高、収納家具、明るい連続窓など、生活に配慮したヴォーリズ建築の特徴が表れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010301"},{"id":"00005180","register_sub_id":"101","register_pk":"106170","name":"飯田家住宅内門","kana":"いいだけじゅうたくうちもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県安曇野市豊科高家604-1","lat":36.26891459,"lng":137.92105266,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口1.8m","structure_material":"木造","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0248","desc":"主屋南東の庭園を囲む土塀に開く。主屋の正面東側に西面する。間口６尺の棟門形式で，屋根は切妻造の桟瓦葺で，わずかに反りをつける。大棟の棟込は七宝つなぎで飾る。両開の板扉を吊り込んでいる。主屋の前庭に面し，屋敷構え正面の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005180"},{"id":"00005170","register_sub_id":"101","register_pk":"106160","name":"飯田家住宅質蔵","kana":"いいだけじゅうたくしちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県安曇野市豊科高家604-1","lat":36.269077,"lng":137.92125072,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積66㎡","structure_material":"土蔵造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0238","desc":"主屋座敷棟の北東，文庫蔵の北西に西面して建つ土蔵造２階建である。桁行５間，梁間３間で，置屋根は切妻造，桟瓦葺とし，西面一杯に瓦葺庇をつけ，外壁は白漆喰塗で腰を海鼠壁とする。西面中央の戸口に黒漆喰塗の両開土戸を吊り込む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005170"},{"id":"00005168","register_sub_id":"101","register_pk":"106158","name":"飯田家住宅主屋","kana":"いいだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県安曇野市豊科高家604-1","lat":36.269051,"lng":137.92099,"geo_status":"db","era":"江戸後期／明治後期増築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋一部2階建、鉄板葺、建築面積520㎡","structure_material":"木造平屋一部2階建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0236","desc":"酒造業飯野屋の住宅。敷地中央に南面して建つ。間口１０間，奥行８間半の妻入で，切妻造，鉄板葺の屋根は元は石置屋根であった。四面に瓦葺庇がつく。内部は西半が土間，東半が居室で，東に別棟の座敷が突出する。安曇野地方の本棟造の大規模住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005168"},{"id":"00005169","register_sub_id":"101","register_pk":"106159","name":"飯田家住宅文庫蔵・隠居屋","kana":"いいだけじゅうたくぶんこぐら・いんきょや","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県安曇野市豊科高家604-1","lat":36.26893438,"lng":137.92128383,"geo_status":"db","era":"明治8／明治初期増築","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積96㎡","structure_material":"土蔵造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0237","desc":"主屋の東，敷地東辺に建つ土蔵造２階建で，桁行６間半，梁間３間で南側２間半を隠居所とし，南東に上雪隠がつく。切妻造の置屋根は桟瓦葺で，軒裏を漆喰塗とし，西側に瓦葺庇がつく。外壁は白漆喰塗で腰を亀甲形の海鼠壁とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005169"},{"id":"00005181","register_sub_id":"101","register_pk":"106171","name":"飯田家住宅塀","kana":"いいだけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県安曇野市豊科高家604-1","lat":36.26870318,"lng":137.9211513,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、延長63m","structure_material":"木造","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0249","desc":"主屋の南東，座敷棟の前に広がる庭園を囲む土塀である。主屋座敷棟の西端から南へ延び，敷地南辺と東辺を画して隠居蔵の南東隅に至る延長６３ｍ。石垣上に１間置きに柱を立て，白漆喰塗とする。屋根は瓦葺とする。敷地南東部の屋敷構えの景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005181"},{"id":"00005171","register_sub_id":"101","register_pk":"106161","name":"飯田家住宅味噌蔵","kana":"いいだけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県安曇野市豊科高家604-1","lat":36.269157,"lng":137.92120948,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0239","desc":"質蔵の北西に南を正面にして東西棟で建つ土蔵造２階建。桁行３間，梁間２間で，切妻造，桟瓦葺とする。南面中央に戸口を設け片引戸を建て込む。東面に窓を開く。軒の出がやや大きく，外壁を白漆喰塗とし，垂木と桁を塗り込め，腰を下見板張とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005171"},{"id":"00005178","register_sub_id":"101","register_pk":"106168","name":"飯田家住宅物置二","kana":"いいだけじゅうたくものおきに","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県安曇野市豊科高家604-1","lat":36.26897476,"lng":137.92064621,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積87㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0246","desc":"敷地の南西隅を囲むように建つ木造平屋建である。物置一の南から南へ延び，矩折れで門番所に接続する。桁行延１６間，梁間１間半で，切妻造，桟瓦葺とする。敷地外側に面する西壁と南壁は大壁造の白漆喰塗で，腰を下見板張とし，敷地内側は吹放ちとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005178"},{"id":"00005179","register_sub_id":"101","register_pk":"106169","name":"飯田家住宅門番所","kana":"いいだけじゅうたくもんばんじょ","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県安曇野市豊科高家604-1","lat":36.2689369,"lng":137.92075934,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積35㎡、門及び塀付","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0247","desc":"敷地南西部，物置二の東端に接続する木造平屋建。東西棟で，桁行３間半，梁間３間，切妻造，桟瓦葺の棟中央に煙出しの越屋根を載せる。外壁は真壁造の白漆喰塗で，北面中央に戸口を設けて引違戸を建て込む。主屋との間に瓦葺の土塀を設け，冠木門を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005179"},{"id":"00004956","register_sub_id":"101","register_pk":"105946","name":"市川家住宅主屋","kana":"いちかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県佐久市大字中込字石神594","lat":36.24093852,"lng":138.46788,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積269㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"20 － 0200","desc":"寄棟造，平屋建，平入で，ほぼ南を正面として建つ。西側は鍵形の土間，床上部は表側に東に向けて台所，茶ノ間，座敷を並べ，その東に増築された切妻造の座敷が取り付く。屋根や外壁は改変されているが，軸組や小屋組の主体部は江戸末期の形式を保持している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004956"},{"id":"00004957","register_sub_id":"101","register_pk":"105947","name":"市川家住宅土蔵","kana":"いちかわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県佐久市大字中込字石神594","lat":36.24082366,"lng":138.46770897,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積46㎡","structure_material":"土蔵造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"20 － 0201","desc":"敷地南辺の西寄りにあり，米等の収納に用いられていた。東西棟の切妻造平屋建，桟瓦葺，平入で，北面に扉口を構えて，下屋を設ける。外壁は漆喰塗で，軒廻りには鉢巻を廻し，小窓にも縁取りを施す。屋敷正面の構えをつくるとともに，街路景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004957"},{"id":"00006619","register_sub_id":"101","register_pk":"107602","name":"井上家住宅表門","kana":"いのうえけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代1446-4他","lat":36.55906123,"lng":138.19813658,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口3.0m","structure_material":"木造","registered":"2007.12.05(平成19.12.05)","register_no":"20 － 0327","desc":"敷地の東辺中央、主屋の外壁線よりやや後退して建つ。間口３．０ｍの腕木門で、中央に門口１．５ｍの引分戸を開き、屋根は切妻造桟瓦葺。両脇の小脇壁は中塗仕上げで、正面腰下を竪板張とし、両端から土塀が矩折れに延びる。端正な造りの表門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006619"},{"id":"00006618","register_sub_id":"101","register_pk":"107601","name":"井上家住宅主屋","kana":"いのうえけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代1446-4他","lat":36.55912547,"lng":138.19806679,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積113㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"20 － 0326","desc":"敷地の北西角寄りに建つ。桁行７間梁間５間半、寄棟造茅葺で、現在は鉄板を被せている。通りに面した妻面では半間毎の柱と土壁を表し、表門と連続した壁面を構成。２間幅の物見格子を設けるなど、武家屋敷の面影を伝え、落ち着きのある景観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006618"},{"id":"00001385","register_sub_id":"101","register_pk":"102375","name":"今井家住宅（今井御小休本陣）板蔵","kana":"いまいけじゅうたく（いまいおこやすみほんじん）いたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県岡谷市今井1832","lat":36.08555448,"lng":138.04451879,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、鉄板葺、建築面積64㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"20 － 0028","desc":"主屋の北方東寄りに建つ，板囲いの簡易な蔵で，正面一間通りは吹き放しとする。背後に建つ木小屋で製材した板材を収納した施設と伝える。風食等の状況や，主屋や蔵等の他の付属屋とは方位が振れていることから，これらより古い時期の建物である可能性がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001385"},{"id":"00001390","register_sub_id":"101","register_pk":"102380","name":"今井家住宅（今井御小休本陣）井戸","kana":"いまいけじゅうたく（いまいおこやすみほんじん）いど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県岡谷市今井1832","lat":36.08523755,"lng":138.04444972,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石積深さ6m、木造上屋付き、建築面積0.74㎡","structure_material":"石積深さ6m","registered":"1999.10.14(平成11.10.14)","register_no":"20 － 0033","desc":"主屋の東に隣接して設けられた石積みの井戸で，深さは約６ｍ。開削時期は明らかでないが，現在の主屋の建設と同じ頃と思われる。井戸枠上に建つ上屋（井戸屋形）は，大正頃の建設になり，主屋側の西面に板扉を設け，他の３方を板壁とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001390"},{"id":"00001387","register_sub_id":"101","register_pk":"102377","name":"今井家住宅（今井御小休本陣）表門","kana":"いまいけじゅうたく（いまいおこやすみほんじん）おもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県岡谷市今井1832","lat":36.08507748,"lng":138.04427076,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造薬医門、鉄板葺、間口5.1m、奥行1.5m","structure_material":"木造薬医門","registered":"1999.10.14(平成11.10.14)","register_no":"20 － 0030","desc":"一間薬医門の形式になり，中央に両開き板扉を構え，脇に潜り戸を備える。屋根は切妻造，むくり付きで，銅板葺とする。中山道の間宿であった旧今井村にあって大名等の通行の際の休憩所として用いられた旧家の格式をうかがわせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001387"},{"id":"00001384","register_sub_id":"101","register_pk":"102374","name":"今井家住宅（今井御小休本陣）木蔵","kana":"いまいけじゅうたく（いまいおこやすみほんじん）きぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県岡谷市今井1832","lat":36.08561066,"lng":138.04419786,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、鉄板葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"20 － 0027","desc":"主屋の西北方，米蔵の北に隣接して東面して建ち，当家の普請に必要な木材を納めた蔵。真壁造，２階建てで，屋根は切妻造，鉄板葺きの簡易な建物。上下階とも正面中央二間を出入り口とする。上下階とも前面に吹き放しの庇を設け，本屋根を葺き下ろす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001384"},{"id":"00001389","register_sub_id":"101","register_pk":"102379","name":"今井家住宅（今井御小休本陣）木小屋","kana":"いまいけじゅうたく（いまいおこやすみほんじん）きごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県岡谷市今井1832","lat":36.08565511,"lng":138.04453048,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、鉄板葺、建築面積40㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"20 － 0032","desc":"屋敷地北方に広がる屋敷林を背後にして建つ簡素な製材作業用の小屋。東西北の三面に貫を廻し，南正面は長大な胴差しを渡して開放とし，壁は設けない。当家の普請のための作業所として建てられたものといい，西に広がる空閑地は屋外作業場と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001389"},{"id":"00001383","register_sub_id":"101","register_pk":"102373","name":"今井家住宅（今井御小休本陣）米蔵","kana":"いまいけじゅうたく（いまいおこやすみほんじん）こめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県岡谷市今井1832","lat":36.08551797,"lng":138.04419707,"geo_status":"db","era":"寛政1","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"土蔵造2階建、鉄平石葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"20 － 0026","desc":"主屋の西北方，文庫蔵の北に隣接して並び建つ２階建ての土蔵。東正面に両開き土扉を設け，周囲腰壁に雨除け板を備え，南妻２階に窓を設ける。屋根は，切妻造の置き屋根形式で，鉄平石葺とする。祈祷札により建築年代が知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001383"},{"id":"00001381","register_sub_id":"101","register_pk":"102371","name":"今井家住宅（今井御小休本陣）主屋","kana":"いまいけじゅうたく（いまいおこやすみほんじん）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県岡谷市今井1832","lat":36.08532076,"lng":138.04426118,"geo_status":"db","era":"明和9","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積450㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"20 － 0024","desc":"中山道の塩尻峠東口に位置し，代々名主を務めた旧家。高島藩主の巡検や，参勤交代の際の休憩所として知られる。主屋は本屋の前面に式台玄関を備えた張出し部を設けた大規模かつ質の高い建築で，本屋，張出し部ともに切妻造，妻入りとする独特の形式を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001381"},{"id":"00001386","register_sub_id":"101","register_pk":"102376","name":"今井家住宅（今井御小休本陣）水車小屋","kana":"いまいけじゅうたく（いまいおこやすみほんじん）すいしゃごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県岡谷市今井1832","lat":36.08549345,"lng":138.04410038,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造2階建、鉄板葺、建築面積7.3㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"20 － 0029","desc":"屋敷地の西辺を北から流れる水路に沿って屋敷内に設けられた水車小屋。木造，２階建てで，板壁で囲い，切妻造の屋根をかけた小規模かつ簡易な建物。屋敷の重要な構成要素のひとつであり，現存する水車小屋としても数少ないものである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001386"},{"id":"00001388","register_sub_id":"101","register_pk":"102378","name":"今井家住宅（今井御小休本陣）中門","kana":"いまいけじゅうたく（いまいおこやすみほんじん）ちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県岡谷市今井1832","lat":36.08511459,"lng":138.04424379,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造薬医門、銅板葺、間口2.1m、奥行0.8m、土塀付","structure_material":"木造薬医門","registered":"1999.10.14(平成11.10.14)","register_no":"20 － 0031","desc":"主屋の前方に，東面して中門が建ち，両脇に土塀が付属する。玄関廻りと庭園を隔す施設であり，南に土塀が接続する。中門は一間薬医門の形式で，両開き板戸を構える。土塀は真壁造，白漆喰塗り，腰下見板張りで，北は主屋，南は表門に接続する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001388"},{"id":"00001382","register_sub_id":"101","register_pk":"102372","name":"今井家住宅（今井御小休本陣）文庫蔵","kana":"いまいけじゅうたく（いまいおこやすみほんじん）ぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県岡谷市今井1832","lat":36.08546021,"lng":138.04412252,"geo_status":"db","era":"文久1","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"土蔵造2階建、鉄平石葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"20 － 0025","desc":"主屋の西北隅に隣接して建つ２階建ての土蔵。主屋に面する東正面に両開きの土戸を構える。周囲の腰壁に雨除け板を備え，南妻の各階に窓を設ける。屋根は切妻造の置き屋根形式で，当地域に多い鉄平石葺とする。築造の記録が残り建築年代が明らか。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001382"},{"id":"00001391","register_sub_id":"101","register_pk":"102381","name":"今井家住宅（今井御小休本陣）屋敷神","kana":"いまいけじゅうたく（いまいおこやすみほんじん）やしきがみ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県岡谷市今井1832","lat":36.08562807,"lng":138.04414155,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、鉄板葺、建築面積1.1㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"20 － 0034","desc":"屋敷の西辺北部に設けられた，当家の屋敷神をまつる小祠。石積み基壇上に南面して建ち，正面１間，側面１間で，正面に向拝を設ける。屋根は正面入母屋造，背面切妻造とする。現在の建物は昭和初期頃に再建したものであり，屋敷の重要な構成要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001391"},{"id":"00010451","register_sub_id":"101","register_pk":"199410","name":"岩垂家住宅主屋","kana":"いわだれけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県塩尻市大字宗賀字床尾2007","lat":36.096319,"lng":137.929963,"geo_status":"db","era":"天保7(1836)／江戸末期・昭和40頃改修","year":1836,"year_source":"db","year_min":1836,"year_max":1836,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積274㎡","structure_material":"木造平屋一部2階建","registered":"2015.03.26(平成27.03.26)","register_no":"20 － 0479","desc":"郊外の集落内に所在する本棟造民家。東西棟で東妻を正面とし、出格子を設けて雀踊りを載せ、正背面に下屋を通す。南側に三列に居室を配し、正面に構える玄関の脇に上段の座敷を張出す。年代の明らかな本棟造民家として価値があり、座敷の造作も上質である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010451"},{"id":"00014821","register_sub_id":"101","register_pk":"519079","name":"恵比寿屋原家住宅主屋","kana":"えびすやはらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上伊那郡宮田村3272","lat":35.76851111,"lng":137.94098889,"geo_status":"db","era":"江戸後期／昭和中期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、鉄板葺、建築面積181㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"20 - 0643","desc":"伊那街道の宮田宿に所在する旧旅籠で、街道に東面して建つ。二階建、切妻造平入、鉄板葺で、正面に桟瓦葺の下屋を設ける。正面は一階中央を出入口とし、二階に格子を建てる。内部は中土間を通して、南北列に座敷など配する。宿場町の様相を伝える大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014821"},{"id":"00014822","register_sub_id":"101","register_pk":"519080","name":"恵比寿屋原家住宅土蔵","kana":"えびすやはらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上伊那郡宮田村3272","lat":35.76845833,"lng":137.94077778,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土造2階建、瓦葺、建築面積28㎡","structure_material":"土造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"20 - 0644","desc":"主屋の西後方に東西棟で建つ。土蔵造二階建、切妻造、置屋根桟瓦葺で、東妻に戸口を開き、桟瓦葺下屋を設ける。小屋は牛梁に太い垂木を架ける。外壁漆喰塗で腰を海鼠壁、戸口と二階の小窓に掛子塗扉を開く。丁寧な左官仕事の土蔵で敷地西部の景観に寄与。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014822"},{"id":"00005853","register_sub_id":"101","register_pk":"106839","name":"大木家住宅旧主屋","kana":"おおきけじゅうたくきゅうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代1501","lat":36.558945,"lng":138.196259,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺（鉄板仮葺）一部瓦葺、建築面積99㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0277","desc":"松代城下の南，象山北麓に位置する。街路に北面する敷地の北西部に建つ木造平屋建で，屋根は寄棟造の茅葺（鉄板仮葺）とし，北側下屋と南側庇を瓦葺とする。南の庭側を縁とし，床棚を構えた８畳座敷と６畳間を配す。旧武家住宅の落ち着いた外観をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005853"},{"id":"00011955","register_sub_id":"101","register_pk":"211099","name":"大嶋家住宅主屋","kana":"おおしまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県松本市大字笹賀4143","lat":36.183066,"lng":137.941867,"geo_status":"db","era":"安政4年（1857）／昭和24年頃・平成6年改修","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"木造2階建、銅板葺、建築面積267㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"20 - 0514","desc":"田園地帯の敷地北西に東面する本棟造民家。間口一六メートルと広く、正面に下屋を設けて中央に式台を構え、妻壁に出格子の窓、棟に雀踊りを飾り、本棟造の特徴と格式を備える。居室は三列構成でナカオエを中心とする。座敷部の造作も上質な幕末期の大型民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011955"},{"id":"00008458","register_sub_id":"101","register_pk":"134854","name":"荻上家住宅主屋","kana":"おぎうえけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県塩尻市大字宗賀字平出714","lat":36.10067638,"lng":137.9498162,"geo_status":"db","era":"江戸末期／明治前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、鉄板葺、建築面積225㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"20 － 0371","desc":"平出集落の東端に位置する。西面する切妻造妻入鉄板葺、正面一四メートル奥行一四メートルの木造つし二階建。北に土間や、もとの馬屋を設け、南側に二列六室に座敷やオエ、寝間ほかを配する。典型的な本棟造で、座敷飾りなどに洗練した意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008458"},{"id":"00012532","register_sub_id":"101","register_pk":"367827","name":"小﨑家住宅土蔵","kana":"おざきけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県中野市大字栗林字松原642","lat":36.748562,"lng":138.333954,"geo_status":"geocoded","era":"明治前期／昭和49年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積43㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"20 － 0535","desc":"千曲川東岸にある牧山集落の名主宅。家財等を収納した土蔵で、敷地後方に東面して建つ。土蔵造二階建、置屋根式の切妻造桟瓦葺で、正面中央に戸口を設けて下屋を通す。急勾配屋根など地域的な特色を備えるとともに伝統的な農家の屋敷構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012532"},{"id":"00012533","register_sub_id":"101","register_pk":"367828","name":"小﨑家住宅長屋門","kana":"おざきけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県中野市大字栗林字松原642","lat":36.748562,"lng":138.333954,"geo_status":"geocoded","era":"明治前期／昭和49年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、瓦葺、建築面積79㎡","structure_material":"土蔵造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"20 － 0536","desc":"街道に東面する敷地正面に建つ。切妻造桟瓦葺の平屋建で南寄りに門口を開き、外壁は大壁で軒裏まで塗込める。北室は西面、南室は門口内の北面に出入口を設ける。内部は床を板敷、根太天井として小屋裏を繭室とする。上層農家の屋敷構えの核をなす豪壮な表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012533"},{"id":"00005838","register_sub_id":"101","register_pk":"106824","name":"小山田家住宅主屋","kana":"おやまだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代8","lat":36.564644,"lng":138.19754,"geo_status":"db","era":"嘉永2","year":1849,"year_source":"db","year_min":1849,"year_max":1849,"year_label":null,"structure":"木造2階建、銅板葺、建築面積98㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0269","desc":"敷地の東辺中央，街路に面して開く薬医門形式の表門である。間口は８尺で，４尺控えて控柱が立つ。屋根は切妻造，桟瓦葺である。男梁の正面側を木鼻に造り，出桁上の組物と実肘木で桁を受けている。門扉は両開の板戸で，左手の脇塀に潜戸を設けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005838"},{"id":"00005844","register_sub_id":"101","register_pk":"106830","name":"小山田家住宅番所","kana":"おやまだけじゅうたくばんしょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代8","lat":36.564545,"lng":138.197617,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0270","desc":"敷地の南面中央，門の西に位置する木造平屋建である。桁行２間，梁間１間半の南北棟で，切妻造，桟瓦葺，南面破風に懸魚を飾る。真壁造の竪板張で，街路に面した南壁の腰は簓子下見板張とし，木格子窓を開く。東面の入口には板戸を建て込む。内部は板敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005844"},{"id":"00005159","register_sub_id":"101","register_pk":"106149","name":"恩田家住宅主屋","kana":"おんだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県長野市松代町松代1504-1","lat":36.559635,"lng":138.197372,"geo_status":"db","era":"大正14頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積139㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0227","desc":"東西に長い敷地に大きく前庭を取って建つ桁行５間半，梁間３間の木造平屋建で，切妻造，桟瓦葺とする。西面に１間の金属板葺の下屋をつけて玄関とし，玄関脇に円形の下地窓を開く。南と北に瓦葺庇の縁がつく。武家住宅の形式を残した建築となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005159"},{"id":"00014377","register_sub_id":"101","register_pk":"511366","name":"鶴樓（福井家別荘主屋）","kana":"かくろう（ふくいけべっそうおもや）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県北佐久郡軽井沢町大字軽井沢字北卯ツ木原291","lat":36.36023056,"lng":138.63060556,"geo_status":"db","era":"昭和16年","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造2階建、瓦葺、建築面積75㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0622","desc":"ヴォーリズ建築事務所設計の別荘。木造２階建切妻造桟瓦葺。外観は下見板張で暖炉の石積が目を引く。１階の居間と食堂は衝立で、２階は続き間座敷として、各階緩やかに二室に区切り、大きな出窓を開け眺望を誇る。洋室の用材吟味し、数寄屋の佇まいを呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014377"},{"id":"00001188","register_sub_id":"101","register_pk":"102178","name":"片倉家住宅主屋","kana":"かたくらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県岡谷市川岸上1-21-6","lat":36.05298045,"lng":138.03303738,"geo_status":"db","era":"18世紀中頃","year":1750,"year_source":"estimated","year_min":1731,"year_max":1770,"year_label":"18世紀中頃","structure":"木造平屋建，茅葺，建築面積215㎡","structure_material":"木造平屋建","registered":"1999.07.08(平成11.07.08)","register_no":"20 － 0014","desc":"諏訪湖を源に発する天竜川の流口付近に位置する。平面は前半に土間や台所等、背面側に居室部を置く特異な間取りを原型とする農家で、幕末や明治期に増改築が行われた。わが国の機械製糸工業界のリーダーであった片倉兼太郎の住家としても知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001188"},{"id":"00001189","register_sub_id":"101","register_pk":"102179","name":"片倉家住宅西の蔵","kana":"かたくらけじゅうたくにしのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県岡谷市川岸上1-21-6","lat":36.0529679,"lng":138.03284969,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造２階建，金属板葺，建築面積25㎡","structure_material":"土蔵造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"20 － 0015","desc":"主屋の西側に建ち並ぶ３棟の土蔵のうち、最も北側に位置する土蔵で、屋根は切妻造、鉄平石葺の置屋根をかける。間口３間、奥行２間半と小規模な造りになり、内部は２階建とする。もとは家財類を収納した漆喰仕上げの土蔵で、扉口の構えが特徴的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001189"},{"id":"00001192","register_sub_id":"101","register_pk":"102182","name":"片倉家住宅文庫蔵","kana":"かたくらけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県岡谷市川岸上1-21-6","lat":36.05293304,"lng":138.03323638,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造３階建，鉄板葺，建築面積65㎡","structure_material":"土蔵造３階建","registered":"1999.07.08(平成11.07.08)","register_no":"20 － 0018","desc":"屋敷地東南の道際に建つ３階建土蔵で、１階は西面の庇を取り込む特異な形態になる。屋根は鉄板葺の置屋根とする。間口５間半、奥行３間半と規模は比較的大きい。内部は、１階が２室に区分されるが、２，３階は１室とする。元は米蔵その他に使用された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001192"},{"id":"00001190","register_sub_id":"101","register_pk":"102180","name":"片倉家住宅味噌蔵","kana":"かたくらけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県岡谷市川岸上1-21-6","lat":36.05291707,"lng":138.03287659,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造２階建，金属板葺，建築面積19㎡","structure_material":"土蔵造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"20 － 0016","desc":"主屋西側に建つ３棟の土蔵のうち、中央に位置する２階建の土蔵。最後に建てられたためか、間口は正面が３間弱、背面側は２間と台形状の平面になる。内部は土間とし、屋根は西の蔵と一体の置屋根をかけて正面側は軒の深い土庇とし、作業空間を確保する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001190"},{"id":"00001191","register_sub_id":"101","register_pk":"102181","name":"片倉家住宅南の蔵","kana":"かたくらけじゅうたくみなみのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県岡谷市川岸上1-21-6","lat":36.05287359,"lng":138.03289396,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造２階建，金属板葺，建築面積29㎡","structure_material":"土蔵造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"20 － 0017","desc":"味噌蔵の南に位置する２階建の生活雑器類を収納した土蔵である。屈曲する道に沿うようにやや棟筋を振って建つ。奥行きは３棟とも同じ２間半であるが、間口は３間半と最も広い。鉄平石葺の置屋根とする屋根は、一段低くなって外観に変化を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001191"},{"id":"00008985","register_sub_id":"101","register_pk":"162345","name":"嘉門次小屋囲炉裏の間","kana":"かもんじごやいろりのま","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市安曇4469-1","lat":36.25328629,"lng":137.66418459,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、板葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0382","desc":"上高地から梓川を遡上した明神池畔の樹林内に南北棟で建つ。木造、桁行５．５ｍ梁間５．０ｍ、切妻造石置板葺である。外部は板張で、内部は板敷として大きな囲炉裏を設け、東側を土間とする。大正期における山人の生活様態をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008985"},{"id":"00003974","register_sub_id":"101","register_pk":"104964","name":"北村家住宅局舎","kana":"きたむらけじゅうたくきょくしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県長野市若穂川田2805","lat":36.603504,"lng":138.23439,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積59㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"20 － 0174","desc":"敷地北側西寄りに建ち，東側を門と接する。土蔵造，桟瓦葺で，置屋根形式とする。大正中頃から昭和１４年頃まで郵便局舎として用いられ，北面東寄りの庇はその当時入口が設けられていた名残である。街路に面する土蔵として，近代の集落景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003974"},{"id":"00003972","register_sub_id":"101","register_pk":"104962","name":"北村家住宅主屋","kana":"きたむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市若穂川田2805","lat":36.60328107,"lng":138.23443965,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積216㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"20 － 0172","desc":"旧川田宿の中心地に建つ木造２階建，切妻造，桟瓦葺の居宅。棟札より近隣の大工中條豊吉の手により建てられたことがわかる。北側を正面とし，２階部は当初養蚕のために用いられていたが，近年居室に改造された。明治期の宿場の景観を今日に伝える建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003972"},{"id":"00003973","register_sub_id":"101","register_pk":"104963","name":"北村家住宅門","kana":"きたむらけじゅうたくもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市若穂川田2805","lat":36.60349571,"lng":138.23454556,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積83㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"20 － 0173","desc":"敷地北側に局舎と並んで建つ。土蔵造２階建で，屋根は切妻造，桟瓦葺とする。西寄りに小庇を掛け，門口を開き，腰部は板張，上部に小窓を設ける。内部は倉庫として用いられ，戦前までは主として米を収めていた。良質の土蔵造長屋門建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003973"},{"id":"00014379","register_sub_id":"101","register_pk":"511368","name":"喜多屋新井家住宅主屋","kana":"きたやあらいけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上伊那郡宮田村3285-19","lat":35.76927778,"lng":137.94121389,"geo_status":"db","era":"江戸後期／昭和10年代・同29年・同50年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、鉄板葺、建築面積263㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0624","desc":"伊那街道の宮田宿に所在する町家。二階建切妻造平入で西面し、北辺の醤油醸造用の表蔵と一体で鉄板葺屋根を架ける。内部は北を土間、南を床上とし、表のみ二階を設け、南西に仏間と床付きの座敷を配す。軒が低く間口長大で、宿場の歴史的景観をつくる主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014379"},{"id":"00012150","register_sub_id":"101","register_pk":"352949","name":"旧朝吹山荘（睡鳩荘）","kana":"きゅうあさぶきさんそう（すいきゅうそう）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県北佐久郡軽井沢町大字長倉字古川206-1","lat":36.32943,"lng":138.597662,"geo_status":"db","era":"昭和6年／平成20年移築","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積189㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"20-521","desc":"実業家朝吹常吉の別荘。Ｌ字型平面で、一階はテラスを中心に暖炉付の広間、和室を、二階は四寝室を配していた。外壁の割丸太や内部の丸太材の化粧梁など野趣豊かで、モルタル塗の煙突をバランスよく配する。ヴォーリズ建築事務所による代表的な山荘建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012150"},{"id":"00014382","register_sub_id":"101","register_pk":"511371","name":"旧井桁屋新井家住宅（タカノ株式会社）新蔵","kana":"きゅういげたやあらいけじゅうたく（たかのかぶしきがいしゃ）しんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県上伊那郡宮田村3287-6","lat":35.76890556,"lng":137.94119167,"geo_status":"db","era":"明治31年／平成14年改修","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造2階建、瓦葺、建築面積33㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0627","desc":"伊那街道の宮田宿に位置する土蔵。二階建切妻造妻入桟瓦葺で、東面に戸口を設けて漆喰塗込の下屋を付す。外壁は漆喰仕上、腰は海鼠壁とする。内部は各階とも一室で北東隅に階段を付す。街道に面して観音開き窓を開き、宿場の歴史的景観をつくる重厚な新蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014382"},{"id":"00014381","register_sub_id":"101","register_pk":"511370","name":"旧井桁屋新井家住宅（タカノ株式会社）文庫蔵","kana":"きゅういげたやあらいけじゅうたく（たかのかぶしきがいしゃ）ぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上伊那郡宮田村3287-2","lat":35.76896111,"lng":137.94141111,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積37㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0626","desc":"伊那街道の宮田宿に位置する文庫蔵。二階建切妻造妻入桟瓦葺で、西面に戸前となる下屋、北面に小庇を付す。外壁は軒裏まで漆喰塗込めとし、腰は海鼠壁とする。内部は各階とも一室で北西隅に階段を設ける。北面窓の土扉を鏝絵で飾り、地域の景観をつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014381"},{"id":"00014367","register_sub_id":"101","register_pk":"511356","name":"旧小穴家住宅主屋","kana":"きゅうおあなけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市北深志一丁目319-1","lat":36.24167778,"lng":137.97166111,"geo_status":"db","era":"大正後期／昭和30年代・同40年代改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積154㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0612","desc":"松本城北の住宅地に所在する近代住宅。平屋建切妻造妻入桟瓦葺で、棟中央両面に切妻破風を設ける。内部は西面の玄関ポーチから中廊下を通し、南に洋室と和室二室、北に台所と風呂を配し、南東に納戸を張出す。玄関ポーチを設けた外観が大正の息吹を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014367"},{"id":"00014368","register_sub_id":"101","register_pk":"511357","name":"旧小穴家住宅書庫","kana":"きゅうおあなけじゅうたくしょこ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県松本市北深志一丁目319-1","lat":36.24163333,"lng":137.97179444,"geo_status":"db","era":"大正後期／昭和35年頃移築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積20㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0613","desc":"松本城北の住宅地にあり、主屋の東に接続する書庫。2階建切妻造妻入桟瓦葺の東西棟で、西に戸口を設ける。西を除く三面に窓を開け、外壁はモルタル塗仕上。内部は各階一室で北辺に階段を設け、小屋組は和小屋とする。窓に鉄扉を吊り、厳重な造りの書庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014368"},{"id":"00014369","register_sub_id":"101","register_pk":"511358","name":"旧小穴家住宅離れ","kana":"きゅうおあなけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県松本市北深志一丁目319-1","lat":36.24159167,"lng":137.97182222,"geo_status":"db","era":"昭和11年／同62年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0614","desc":"近代住宅の主屋南東の離れで結核療養のために建設。平屋建切妻造桟瓦葺、壁は下見板張で、北面に玄関を設ける。内部は東西中央に設えた棚を挟んで、二室の畳敷とし、天井は折上天井漆喰仕上に木枠で縁取り、洋風にまとめる。小規模ながら丁寧な造りの離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014369"},{"id":"00013999","register_sub_id":"101","register_pk":"508259","name":"旧小澤家住宅主屋","kana":"きゅうおざわけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市保福寺町246","lat":36.31270833,"lng":138.02951111,"geo_status":"db","era":"大正2年／令和2年改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階一部3階建、瓦葺、建築面積340㎡","structure_material":"木造2階一部3階建","registered":"2021.10.14(令和3.10.14)","register_no":"20 - 0586","desc":"保福寺宿本陣跡に建つ二階一部三階建切妻造桟瓦葺、妻面に貫を重ねる本棟造風妻入。式台は二箇所で南側は入母屋造玄関を付す。西を土間とし床上部は二列六室で南東に床付一五畳座敷。茶の間は三層吹抜で、天窓から光が差し見応えがある。本陣の格式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013999"},{"id":"00014001","register_sub_id":"101","register_pk":"508261","name":"旧小澤家住宅北土蔵","kana":"きゅうおざわけじゅうたくきたどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県松本市保福寺町246","lat":36.31290556,"lng":138.029475,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積87㎡","structure_material":"木造平屋一部2階建","registered":"2021.10.14(令和3.10.14)","register_no":"20 - 0588","desc":"主屋前方に位置し道路に妻面を見せる。土蔵造二階建で切妻造桟瓦葺置屋根を載せる。外壁は鉢巻付漆喰塗込めで、腰は海鼠壁。内部は三室に区画し掛子塗戸の戸口二箇所。西側は下屋で蔵本体とは区画され南に開口を開ける。旧街道宿場の景観を形成する大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014001"},{"id":"00014000","register_sub_id":"101","register_pk":"508260","name":"旧小澤家住宅離れ","kana":"きゅうおざわけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県松本市保福寺町246","lat":36.31259167,"lng":138.02960833,"geo_status":"db","era":"昭和初期／令和2年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積63㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"20 - 0587","desc":"主屋東に位置する。二階建入母屋造桟瓦葺で北面に玄関、南面に下屋付属。一階の玄関ホールや洋室は壁と折上天井を漆喰塗仕上、腰を板張、ステンドグラスや絵タイルを飾る。二階は一転して続き間座敷。各階ともたちが高く、ガラス戸を多用した瀟洒な近代和風。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014000"},{"id":"00014002","register_sub_id":"101","register_pk":"508262","name":"旧小澤家住宅南土蔵","kana":"きゅうおざわけじゅうたくみなみどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県松本市保福寺町246","lat":36.31277222,"lng":138.02927222,"geo_status":"db","era":"明治41年","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建、瓦葺、建築面積66㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"20 - 0589","desc":"主屋西に東面して位置。土蔵造二階建で切妻造桟瓦葺。漆喰で軒先まで塗込め垂木形をみせ、腰は海鼠壁。内部は一階を三室に区画し中央を土間、両脇を板敷とし、それぞれ戸口を構え引戸を備え実用的。二階は板敷の一室で窓は三箇所。敷地西辺の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014002"},{"id":"00013397","register_sub_id":"101","register_pk":"368482","name":"旧尾張徳川家本邸主屋（八ヶ岳高原ヒュッテ）","kana":"きゅうおわりとくがわけほんていおもや（やつがたけこうげんひゅって）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県南佐久郡南牧村大字海ノ口字西牧場2244-3","lat":35.98946111,"lng":138.43803333,"geo_status":"db","era":"昭和9年／昭和43年移築","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、スレート葺、建築面積446㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"20 － 0566","desc":"尾張徳川家第19代義親が目白に建設した本邸を昭和43年に八ヶ岳へ移築した。ハーフティンバーを基調とし、大小の切妻屋根を組み合わせて変化を付ける。端正な意匠でまとめつつ、内外の木部を手斧で仕上げた温もりある造り。渡辺仁による邸宅建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013397"},{"id":"00009944","register_sub_id":"101","register_pk":"196091","name":"旧恩田重信家住宅主屋","kana":"きゅうおんだしげのぶけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代字竹山町1506","lat":36.55972397,"lng":138.19714617,"geo_status":"db","era":"江戸末期／明治前期・平成23改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺及び瓦葺、建築面積139㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"20 － 0438","desc":"南北棟で桁行五間半梁間四間の主体部に、東西棟で桁行八間半梁間二間半の台所などが附属する。主体部は茅葺で、内外ともに壁を漆喰で仕上げる。痕跡から西側の納戸部分はもと九尺幅の式台であったと考えられ、旧松代城下の武家住宅の特徴を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009944"}];
